import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { fetchAllRows } from "@/lib/supabase/fetch-all";

async function checkAuth(req: NextRequest) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  const { data: pengguna } = await supabase
    .from("pengguna")
    .select("level")
    .eq("username", user.email?.split("@")[0])
    .single();
  if (
    !pengguna ||
    (pengguna.level !== "ADMIN" && pengguna.level !== "OWNER")
  ) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }
  return null;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function parseParams(req: NextRequest) {
  const sp = (key: string, fallback: string): string =>
    req.nextUrl.searchParams.get(key) ?? fallback;
  const np = (key: string, fallback: number): number => {
    const v = req.nextUrl.searchParams.get(key);
    return v ? Number(v) : fallback;
  };

  const today = new Date().toISOString().slice(0, 10);
  const start_date = sp("start_date", today);
  const end_date = sp("end_date", today);
  const id_pelanggan = np("id_pelanggan", 0);
  const id_metode_bayar = np("id_metode_bayar", 0);
  const id_kasir = np("id_kasir", 0);
  const search = sp("search", "");
  const page = Math.max(1, np("page", 1));
  const limit = Math.min(200, Math.max(1, np("limit", 50)));
  const sort_by = sp("sort_by", "tgl_transaksi");
  const sort_order = sp("sort_order", "desc") === "asc" ? "asc" : "desc";
  const include_items = sp("include_items", "true") === "true";

  const errors: string[] = [];
  if (!/^\d{4}-\d{2}-\d{2}$/.test(start_date))
    errors.push("start_date tidak valid. Format: YYYY-MM-DD");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(end_date))
    errors.push("end_date tidak valid. Format: YYYY-MM-DD");

  return {
    start_date,
    end_date,
    id_pelanggan,
    id_metode_bayar,
    id_kasir,
    search,
    page,
    limit,
    sort_by,
    sort_order,
    include_items,
    errors,
  };
}

/* ------------------------------------------------------------------ */
/*  GET                                                                */
/* ------------------------------------------------------------------ */

export async function GET(req: NextRequest) {
  try {
    const authErr = await checkAuth(req);
    if (authErr) return authErr;

    const p = parseParams(req);
    if (p.errors.length) {
      return NextResponse.json({ error: p.errors.join("; ") }, { status: 400 });
    }

    const supabase = await createAdminClient();

    const startISO = `${p.start_date}T00:00:00+07:00`;
    const endISO = `${p.end_date}T23:59:59+07:00`;

    /* ---------- build base filter ---------- */
    let countQuery = supabase
      .from("transaksi_keluar")
      .select("*", { count: "exact", head: true })
      .gte("tgl_transaksi", startISO)
      .lte("tgl_transaksi", endISO);

    let dataQuery = supabase
      .from("transaksi_keluar")
      .select(`
        id, no_transaksi, tgl_transaksi, subtotal,
        diskon_persen, diskon_nominal,
        pajak_persen, pajak_nominal,
        total, bayar, kembali, dp, sisa,
        total_hpp, laba_kotor,
        kasir:pengguna!id_kasir(id, nama),
        pelanggan(id, nama_pelanggan, no_hp),
        metode_bayar(id, nama)
      `)
      .gte("tgl_transaksi", startISO)
      .lte("tgl_transaksi", endISO);

    if (p.id_pelanggan) {
      countQuery = countQuery.eq("id_pelanggan", p.id_pelanggan);
      dataQuery = dataQuery.eq("id_pelanggan", p.id_pelanggan);
    }
    if (p.id_metode_bayar) {
      countQuery = countQuery.eq("id_metode_bayar", p.id_metode_bayar);
      dataQuery = dataQuery.eq("id_metode_bayar", p.id_metode_bayar);
    }
    if (p.id_kasir) {
      countQuery = countQuery.eq("id_kasir", p.id_kasir);
      dataQuery = dataQuery.eq("id_kasir", p.id_kasir);
    }
    if (p.search) {
      const s = `%${p.search}%`;
      countQuery = countQuery.or(
        `no_transaksi::text.ilike.${s},pelanggan.nama_pelanggan.ilike.${s}`
      );
      dataQuery = dataQuery.or(
        `no_transaksi::text.ilike.${s},pelanggan.nama_pelanggan.ilike.${s}`
      );
    }

    /* ---------- count ---------- */
    const { count, error: countErr } = await countQuery;
    if (countErr) throw countErr;

    /* ---------- meta aggregates ---------- */
    let aggQuery = supabase
      .from("transaksi_keluar")
      .select("total, total_hpp, laba_kotor, diskon_nominal, pajak_nominal")
      .gte("tgl_transaksi", startISO)
      .lte("tgl_transaksi", endISO);

    if (p.id_pelanggan) aggQuery = aggQuery.eq("id_pelanggan", p.id_pelanggan);
    if (p.id_metode_bayar) aggQuery = aggQuery.eq("id_metode_bayar", p.id_metode_bayar);
    if (p.id_kasir) aggQuery = aggQuery.eq("id_kasir", p.id_kasir);

    const agg = await fetchAllRows(supabase, (db, from, to) =>
      aggQuery.range(from, to)
    );

    const safe = (v: any) => Number(v ?? 0);
    const totalPenjualan = agg!.reduce((s, r) => s + safe(r.total), 0);
    const totalHpp = agg!.reduce((s, r) => s + safe(r.total_hpp), 0);
    const totalLaba = agg!.reduce((s, r) => s + safe(r.laba_kotor), 0);
    const totalDiskon = agg!.reduce((s, r) => s + safe(r.diskon_nominal), 0);
    const totalPajak = agg!.reduce((s, r) => s + safe(r.pajak_nominal), 0);

    /* ---------- paginated data ---------- */
    const from = (p.page - 1) * p.limit;
    const to = from + p.limit - 1;
    const { data: rows, error: dataErr } = await dataQuery
      .order(p.sort_by, { ascending: p.sort_order === "asc" })
      .range(from, to);

    if (dataErr) throw dataErr;

    /* ---------- fetch items (if requested) ---------- */
    const itemsMap: Record<number, any[]> = {};
    if (p.include_items && rows && rows.length > 0) {
      const ids = rows.map((r: any) => r.id);
      const { data: details, error: detErr } = await supabase
        .from("detail_transaksi_keluar")
        .select(`
          id, id_transaksi, id_produk, type_harga_jual,
          harga_modal, harga_jual, diskon_item, qty, jumlah,
          harga_pokok_satuan, total_harga_pokok, profit, kas_masuk,
          produk!id_produk(nama_produk, barcode, kategori!id_kategori(nama))
        `)
        .in("id_transaksi", ids);

      if (detErr) throw detErr;

      for (const d of details ?? []) {
        const tid = d.id_transaksi;
        if (!itemsMap[tid]) itemsMap[tid] = [];
        const prod: any = d.produk ?? {};
        itemsMap[tid].push({
          id: d.id,
          id_produk: d.id_produk,
          nama_produk: prod.nama_produk ?? "",
          barcode: prod.barcode ?? null,
          kategori: (prod.kategori as any)?.nama ?? null,
          type_harga_jual: d.type_harga_jual,
          harga_modal: Number(d.harga_modal ?? 0),
          harga_jual: Number(d.harga_jual ?? 0),
          diskon_item: Number(d.diskon_item ?? 0),
          qty: Number(d.qty ?? 0),
          jumlah: Number(d.jumlah ?? 0),
          harga_pokok_satuan: Number(d.harga_pokok_satuan ?? 0),
          total_harga_pokok: Number(d.total_harga_pokok ?? 0),
          profit: Number(d.profit ?? 0),
        });
      }
    }

    /* ---------- map rows ---------- */
    const data = (rows ?? []).map((r: any) => {
      const pel = r.pelanggan as any;
      const kas = r.kasir as any;
      const mb = r.metode_bayar as any;
      return {
        id: r.id,
        no_transaksi: r.no_transaksi,
        tgl_transaksi: r.tgl_transaksi,
        kasir: kas ? { id: kas.id, nama: kas.nama } : null,
        pelanggan: pel
          ? { id: pel.id, nama: pel.nama_pelanggan, no_hp: pel.no_hp }
          : null,
        metode_bayar: mb ? { id: mb.id, nama: mb.nama } : null,
        subtotal: Number(r.subtotal ?? 0),
        diskon_persen: Number(r.diskon_persen ?? 0),
        diskon_nominal: Number(r.diskon_nominal ?? 0),
        pajak_persen: Number(r.pajak_persen ?? 0),
        pajak_nominal: Number(r.pajak_nominal ?? 0),
        total: Number(r.total ?? 0),
        bayar: Number(r.bayar ?? 0),
        kembali: Number(r.kembali ?? 0),
        total_hpp: Number(r.total_hpp ?? 0),
        laba_kotor: Number(r.laba_kotor ?? 0),
        items: p.include_items ? (itemsMap[r.id] ?? []) : undefined,
        piutang: null,
      };
    });

    const totalPages = Math.max(1, Math.ceil((count ?? 0) / p.limit));

    return NextResponse.json({
      meta: {
        total_transaksi: count ?? 0,
        total_penjualan: totalPenjualan,
        total_hpp: totalHpp,
        total_laba_kotor: totalLaba,
        total_diskon: totalDiskon,
        total_pajak: totalPajak,
        rata_rata_per_transaksi:
          count && count > 0 ? Math.round(totalPenjualan / count) : 0,
        periode: { start: p.start_date, end: p.end_date },
      },
      data,
      pagination: {
        page: p.page,
        limit: p.limit,
        total: count ?? 0,
        total_pages: totalPages,
      },
    });
  } catch (err: any) {
    console.error("GET /api/laporan/penjualan error:", err);
    return NextResponse.json(
      { error: "Terjadi kesalahan saat mengambil data laporan" },
      { status: 500 }
    );
  }
}

"use client";

import { useEffect, useState, useCallback } from "react";
import QRCode from "qrcode";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { RefreshCw, Timer, Loader2 } from "lucide-react";

export default function GenerateQRPage() {
  const [qrData, setQrData] = useState<{ token: string; expired_at: string } | null>(null);
  const [qrDataUrl, setQrDataUrl] = useState<string>("");
  const [loading, setLoading] = useState(false);
  const [timeLeft, setTimeLeft] = useState<number>(0);

  const fetchQR = useCallback(async () => {
    try {
      setLoading(true);
      const res = await fetch("/api/attendance/generate-qr", { method: "POST" });
      if (!res.ok) {
        const errorText = await res.text();
        throw new Error(`Failed to fetch QR: ${res.status} ${errorText}`);
      }
      const data = await res.json();
      if (data.token) {
        const url = await QRCode.toDataURL(data.token, {
          width: 300,
          margin: 2,
          color: {
            dark: "#000000",
            light: "#ffffff",
          },
        });

        setQrData(data);
        setQrDataUrl(url);

        // Use expire_seconds from server for a reliable, timezone-independent countdown
        setTimeLeft(data.expire_seconds || 60);
      }
    } catch (error) {
      console.error("Failed to generate QR:", error);
      alert("Gagal membuat QR code. Silakan coba lagi.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!qrData || timeLeft <= 0) return;

    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          setQrData(null);
          setQrDataUrl("");
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [qrData, timeLeft === 0]);

  const isExpired = qrData && timeLeft <= 0;
  const hasQR = qrDataUrl && !isExpired;

  return (
    <div className="flex-1 p-4 md:p-8 lg:p-12 w-full max-w-4xl mx-auto flex flex-col gap-8">
      <header>
        <h1 className="text-4xl font-light tracking-tight text-foreground">
          Generate QR Attendance
        </h1>
        <p className="text-muted-foreground mt-2">
          Minta karyawan untuk melakukan scan pada kode QR di bawah ini untuk absensi.
        </p>
      </header>

      <div className="flex justify-center mt-8">
        <Card className="w-full max-w-md bg-card border border-border/50 rounded-xl shadow-[0_8px_24px_rgba(0,55,112,0.08),_0_2px_6px_rgba(0,55,112,0.04)] overflow-hidden">
          <CardHeader className="text-center pb-2 bg-muted/30 border-b border-border/50">
            <CardTitle className="text-2xl font-light">QR Absensi</CardTitle>
            <CardDescription>Berlaku selama {timeLeft > 0 ? timeLeft : 30} detik</CardDescription>
          </CardHeader>
          <CardContent className="flex flex-col items-center gap-8 py-10">
            <div className="bg-background p-4 rounded-2xl relative w-full max-w-[282px] mx-auto">
              {loading && !qrDataUrl ? (
                <div className="w-full aspect-square flex items-center justify-center">
                  <Loader2 className="w-8 h-8 animate-spin text-primary" />
                </div>
              ) : hasQR ? (
                <img 
                  src={qrDataUrl} 
                  alt="QR Attendance" 
                  className={`w-full aspect-square transition-opacity duration-300 ${loading ? "opacity-50" : "opacity-100"}`}
                />
              ) : (
                <div className="w-full aspect-square flex flex-col items-center justify-center text-center p-6 bg-muted/20 rounded-xl border-2 border-dashed border-border/50">
                  <p className="text-sm text-muted-foreground mb-4">
                    {isExpired ? "QR Code telah kedaluwarsa." : "Klik tombol di bawah untuk membuat QR code baru."}
                  </p>
                  <Button 
                    onClick={fetchQR} 
                    className="gap-2"
                    disabled={loading}
                  >
                    <RefreshCw className={`w-4 h-4 ${loading ? "animate-spin" : ""}`} />
                    Buat QR Baru
                  </Button>
                </div>
              )}
              {loading && hasQR && (
                <div className="absolute inset-0 flex items-center justify-center bg-background/50 backdrop-blur-[1px]">
                  <Loader2 className="w-8 h-8 animate-spin text-primary" />
                </div>
              )}
            </div>

            <div className="flex flex-col items-center gap-4 w-full">
              <div className="flex items-center gap-2 text-2xl font-mono tabular-nums bg-muted px-6 py-2 rounded-full border border-border">
                <Timer className={`w-6 h-6 ${timeLeft < 10 ? "text-destructive" : "text-primary"}`} />
                <span className={timeLeft < 10 ? "text-destructive font-medium" : "text-foreground"}>
                  00:{timeLeft.toString().padStart(2, "0")}
                </span>
              </div>

              {hasQR && (
                <Button 
                  onClick={fetchQR} 
                  variant="outline" 
                  className="w-full h-12 gap-2 mt-2"
                  disabled={loading}
                >
                  <RefreshCw className={`w-4 h-4 ${loading ? "animate-spin" : ""}`} />
                  Refresh Manual
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-6 text-sm">
        <div className="p-4 rounded-lg bg-muted/50 border border-border flex gap-4">
          <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
            <RefreshCw className="w-4 h-4 text-primary" />
          </div>
          <div>
            <h4 className="font-medium mb-1">Informasi</h4>
            <p className="text-muted-foreground leading-relaxed">QR code harus diperbarui secara manual untuk memastikan keamanan data absensi.</p>
          </div>
        </div>
        <div className="p-4 rounded-lg bg-muted/50 border border-border flex gap-4">
          <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
            <Timer className="w-4 h-4 text-primary" />
          </div>
          <div>
            <h4 className="font-medium mb-1">Cara Penggunaan</h4>
            <p className="text-muted-foreground leading-relaxed">Klik &quot;Buat QR Baru&quot;, lalu minta karyawan melakukan scan menggunakan menu &quot;Scan QR&quot;.</p>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import { BrowserMultiFormatReader } from "@zxing/browser";
import { NotFoundException, DecodeHintType, BarcodeFormat } from "@zxing/library";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Camera, RefreshCw, CheckCircle2, AlertCircle, Loader2, MapPin } from "lucide-react";
import { useRouter } from "next/navigation";

type ScanStatus = "idle" | "requesting_permission" | "scanning" | "processing" | "success" | "error";

export default function AttendanceScanPage() {
  const videoRef = useRef<HTMLVideoElement>(null);
  const readerRef = useRef<BrowserMultiFormatReader | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const [status, setStatus] = useState<ScanStatus>("idle");
  const [errorMsg, setErrorMsg] = useState<string>("");
  const [successMsg, setSuccessMsg] = useState<string>("");
  const router = useRouter();

  const stopCamera = useCallback(() => {
    if (readerRef.current) {
      BrowserMultiFormatReader.releaseAllStreams();
      readerRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
  }, []);

  const getCurrentPosition = useCallback((): Promise<{ latitude: number; longitude: number } | null> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve(null);
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (pos) => resolve({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
        () => resolve(null),
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 30000 }
      );
    });
  }, []);

  const handleScan = useCallback(async (token: string) => {
    try {
      setStatus("processing");

      // Ambil koordinat GPS untuk geofencing (check-in)
      const position = await getCurrentPosition();

      // Try Check-in first, if already checked in, try checkout
      const checkinRes = await fetch("/api/attendance/checkin", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          token,
          device_info: navigator.userAgent,
          latitude: position?.latitude ?? null,
          longitude: position?.longitude ?? null,
        })
      });

      let checkinData;
      try {
        checkinData = await checkinRes.json();
      } catch (_e) {
        checkinData = { error: "Failed to parse response from server" };
      }

      if (checkinRes.ok) {
        setStatus("success");
        setSuccessMsg(`Check-in Berhasil! Status: ${checkinData.status}`);
        return;
      }

      // If already checked in, try checkout
      const alreadyCheckedIn =
        checkinData.code === "ALREADY_CHECKED_IN" ||
        checkinData.error?.toLowerCase().includes("already checked in");
      if (alreadyCheckedIn) {
        const checkoutRes = await fetch("/api/attendance/checkout", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ token })
        });

        let checkoutData;
        try {
          checkoutData = await checkoutRes.json();
        } catch (_e) {
          checkoutData = { error: "Failed to parse response from server" };
        }

        if (checkoutRes.ok) {
          setStatus("success");
          setSuccessMsg("Check-out Berhasil! Sampai jumpa besok.");
        } else {
          setStatus("error");
          setErrorMsg(checkoutData.error || "Gagal melakukan absensi.");
        }
      } else {
        setStatus("error");
        setErrorMsg(checkinData.error || "Gagal melakukan absensi.");
      }
    } catch (_err) {
      setStatus("error");
      setErrorMsg("Terjadi kesalahan koneksi.");
    }
  }, [getCurrentPosition]);

  const startScanning = useCallback(async () => {
    try {
      setStatus("requesting_permission");
      setErrorMsg("");
      setSuccessMsg("");

      // Stop any previous camera session
      stopCamera();

      // 1. Acquire camera stream manually
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: { ideal: "environment" },
          width: { ideal: 1280 },
          height: { ideal: 720 },
        },
      });
      streamRef.current = stream;

      // 2. Attach stream to video element and wait for it to play
      const video = videoRef.current!;
      video.srcObject = stream;
      await video.play();

      // 3. Configure ZXing reader with QR_CODE format
      const hints = new Map();
      hints.set(DecodeHintType.TRY_HARDER, true);
      hints.set(DecodeHintType.POSSIBLE_FORMATS, [BarcodeFormat.QR_CODE]);

      const reader = new BrowserMultiFormatReader(hints);
      readerRef.current = reader;

      // 4. Start continuous decoding from the already-playing stream
      reader.decodeFromStream(stream, video, (result, err) => {
        if (result) {
          // Stop scanning immediately on successful decode
          stopCamera();
          handleScan(result.getText());
        } else if (err && !(err instanceof NotFoundException)) {
          // NotFoundException fires every frame when no QR visible — ignore
          console.warn("[qr-scanner]", err);
        }
      });

      setStatus("scanning");
    } catch (err: unknown) {
      console.error("Scan initialization error:", err);
      setStatus("error");

      const errorName = err instanceof Error ? (err as Error & { name?: string }).name : undefined;
      const errorMessage = err instanceof Error ? err.message : undefined;

      if (errorName === "NotAllowedError") {
        setErrorMsg("Izin kamera ditolak. Silakan berikan izin di pengaturan browser Anda.");
      } else if (errorName === "NotFoundError" || errorName === "DevicesNotFoundError") {
        setErrorMsg("Kamera tidak ditemukan.");
      } else if (errorName === "NotReadableError" || errorName === "AbortError") {
        setErrorMsg("Kamera sedang digunakan aplikasi lain. Tutup aplikasi lain dan coba lagi.");
      } else {
        setErrorMsg(errorMessage || "Gagal memulai scanner.");
      }
    }
  }, [stopCamera, handleScan]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      BrowserMultiFormatReader.releaseAllStreams();
      streamRef.current?.getTracks().forEach((t) => t.stop());
    };
  }, []);

  const isVideoVisible = status === "scanning" || status === "processing";

  return (
    <div className="flex-1 p-4 md:p-8 lg:p-12 w-full max-w-8xl mx-auto flex flex-col gap-8">
      <header>
        <h1 className="text-4xl font-light tracking-tight text-foreground">
          Scan QR Attendance
        </h1>
        <p className="text-muted-foreground mt-2">
          Arahkan kamera ke kode QR yang ada di layar admin.
        </p>
      </header>

      <div className="flex justify-center mt-4">
        <Card className="w-full max-w-md overflow-hidden border-none shadow-lg">
          <CardHeader className=" border-b border-border/50 text-center">
            <CardTitle className="flex items-center justify-center gap-2 py-2">
              <Camera className="w-5 h-5 text-primary" />
              QR Scanner
            </CardTitle>
            <CardDescription>
              Pastikan izin kamera diberikan
            </CardDescription>
          </CardHeader>
          <CardContent className="p-0 relative bg-card aspect-square flex items-center justify-center">
            {/* Video is ALWAYS in the DOM — ZXing needs a mounted element */}
            <video 
              ref={videoRef} 
              className="absolute inset-0 w-full h-full object-cover"
              style={{ visibility: isVideoVisible ? "visible" : "hidden" }}
              muted
              playsInline
              autoPlay
            />

            {status === "idle" && (
              <div className="flex flex-col items-center gap-6 p-8 text-foreground relative z-10">
                <div className="w-20 h-20 rounded-full bg-primary/20 flex items-center justify-center">
                  <Camera className="w-10 h-10 text-primary" />
                </div>
                <Button onClick={startScanning} size="lg" className="px-8 h-12 gap-2">
                  Buka Kamera
                </Button>
              </div>
            )}

            {status === "requesting_permission" && (
              <div className="flex flex-col items-center gap-4 text-foreground relative z-10">
                <Loader2 className="w-10 h-10 animate-spin text-primary" />
                <p>Meminta izin kamera...</p>
              </div>
            )}

            {(status === "scanning" || status === "processing") && (
              <div className="absolute inset-0 z-10 pointer-events-none">
                <div className="absolute inset-0 border-[40px] border-background/80">
                  <div className="w-full h-full border border-primary/30 relative">
                    <div className="absolute top-[-1px] left-[-1px] w-4 h-4 border-t-2 border-l-2 border-primary/70"></div>
                    <div className="absolute top-[-1px] right-[-1px] w-4 h-4 border-t-2 border-r-2 border-primary/70"></div>
                    <div className="absolute bottom-[-1px] left-[-1px] w-4 h-4 border-b-2 border-l-2 border-primary/70"></div>
                    <div className="absolute bottom-[-1px] right-[-1px] w-4 h-4 border-b-2 border-r-2 border-primary/70"></div>

                    {status === "scanning" && (
                      <div className="absolute left-0 right-0 h-0.5 bg-primary/60 animate-[scan_2s_ease-in-out_infinite]"></div>
                    )}
                  </div>
                </div>

                {status === "processing" && (
                  <div className="absolute inset-0 bg-background/80 backdrop-blur-sm flex flex-col items-center justify-center text-foreground gap-4 pointer-events-auto">
                    <Loader2 className="w-10 h-10 animate-spin text-primary" />
                    <p className="font-medium">Memproses absensi...</p>
                  </div>
                )}
              </div>
            )}

            {status === "success" && (
              <div className="flex flex-col items-center gap-6 p-8 text-center relative z-10">
                <div className="w-20 h-20 rounded-full bg-success/20 flex items-center justify-center">
                  <CheckCircle2 className="w-10 h-10 text-success" />
                </div>
                <div>
                  <h3 className="text-xl font-semibold text-foreground mb-2">{successMsg}</h3>
                  <p className="text-muted-foreground">Data absensi telah tersimpan di sistem.</p>
                </div>
                <Button onClick={() => router.back()} variant="outline" className="bg-transparent border-border hover:bg-muted">
                  Kembali
                </Button>
              </div>
            )}

            {status === "error" && (
              <div className="flex flex-col items-center gap-6 p-8 text-center relative z-10">
                <div className="w-20 h-20 rounded-full bg-destructive/20 flex items-center justify-center">
                  <AlertCircle className="w-10 h-10 text-destructive" />
                </div>
                <div>
                  <h3 className="text-xl font-semibold text-foreground mb-2">Absensi Gagal</h3>
                  <p className="text-muted-foreground">{errorMsg}</p>
                </div>
                <Button onClick={startScanning} variant="outline" className="bg-transparent border-border hover:bg-muted gap-2">
                  <RefreshCw className="w-4 h-4" />
                  Coba Lagi
                </Button>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-4">
        <Card className="bg-muted/30 border-none">
          <CardContent className="py-4 px-6">
            <div className="flex items-start gap-4">
              <Camera className="w-5 h-5 text-primary shrink-0 mt-1" />
              <div>
                <p className="font-medium">Izin Kamera</p>
                <p className="text-sm text-muted-foreground leading-relaxed">Pastikan Anda memberikan izin akses kamera untuk melakukan pemindaian kode QR.</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-muted/30 border-none">
          <CardContent className="py-4 px-6">
            <div className="flex items-start gap-4">
              <RefreshCw className="w-5 h-5 text-primary shrink-0 mt-1" />
              <div>
                <p className="font-medium">QR Dinamis</p>
