"use client";

import { useState, useEffect } from "react";
import {
  Calculator,
  AlertCircle,
  Check,
  Loader2,
  Printer,
  Save,
  Wallet,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  fetchCashSummary,
  submitTutupKasir,
  bukaSesiKasir,
} from "../tutup-kasir/actions";

function formatIDR(n: number) {
  return new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n);
}

export default function BukaKasirClient({
  initialSummary,
}: {
  initialSummary: any;
}) {
  const [date, setDate] = useState(new Date().toISOString().slice(0, 10));
  const [summary, setSummary] = useState(initialSummary);
  const [uangAwal, setUangAwal] = useState<string>("");
  const [uangAktual, setUangAktual] = useState<string>("");
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const refreshSummary = async (newDate: string) => {
    setLoading(true);
    const res = await fetchCashSummary(newDate);
    if (res.data) {
      setSummary(res.data);
      setError("");
    } else {
      setError(res.error || "Gagal memuat data");
    }
    setLoading(false);
  };

  useEffect(() => {
    if (date !== initialSummary?.tanggal) {
      refreshSummary(date);
    }
  }, [date]);

  const handleBukaSesi = async () => {
    const num = Number(uangAwal);
    if (uangAwal === "" || isNaN(num) || num <= 0) {
      setError("Masukkan uang awal sesi (float) lebih dari 0");
      return;
    }
    setSubmitting(true);
    setError("");
    setSuccess("");
    const res = await bukaSesiKasir(summary.tanggal, num);
    if (res?.error) {
      setError(res.error);
    } else {
      setSuccess("Sesi kasir berhasil dibuka");
      await refreshSummary(summary.tanggal);
    }
    setSubmitting(false);
  };

  const handleSubmit = async () => {
    const num = Number(uangAktual);
    if (uangAktual === "" || isNaN(num) || num < 0) {
      setError("Masukkan uang aktual di laci");
      return;
    }
    setSubmitting(true);
    setError("");
    setSuccess("");
    const res = await submitTutupKasir({
      tanggal: summary.tanggal,
      uang_aktual: num,
    });
    if (res?.error) {
      setError(res.error);
    } else {
      setSuccess("Tutup kasir berhasil dikonfirmasi");
      await refreshSummary(summary.tanggal);
    }
    setSubmitting(false);
  };

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  if (!summary) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center text-muted-foreground p-8 text-center bg-background border border-border rounded-xl">
        <p>Data tidak ditemukan</p>
      </div>
    );
  }

  const sudahDibuka = summary.sesi?.sudah_dibuka;
  const sudahDitutup = summary.sesi?.sudah_ditutup;
  const saldoAwal = Number(summary.saldo_awal || 0);
  const totalMasuk = Number(summary.total_masuk || 0);
  const totalKeluar = Number(summary.total_keluar || 0);
  const expectedSaldoAkhir = saldoAwal + totalMasuk - totalKeluar;
  const penambahan = Number(summary.penambahan ?? totalMasuk);
  const selisih =
    uangAktual !== "" ? Number(uangAktual) - expectedSaldoAkhir : 0;

  return (
    <>
      <header className="shrink-0 print:hidden">
        <h1 className="text-4xl font-light tracking-tighter text-foreground">
          Kas Kasir
        </h1>
        <p className="text-muted-foreground mt-2">
          Buka sesi dengan uang awal, lalu tutup di akhir hari.
        </p>
      </header>

      <div className="flex-1 flex flex-col min-h-0 bg-background border border-border rounded-[12px] shadow-[0_1px_3px_rgba(0,55,112,0.08)] overflow-hidden relative">
        <div className="flex-1 overflow-y-auto p-6 lg:p-10">
          <div className="max-w-3xl mx-auto space-y-10">
            <div className="flex items-center gap-3">
              <label
                htmlFor="date"
                className="text-sm font-medium text-muted-foreground"
              >
                Shift:
              </label>
              <Input
                id="date"
                type="date"
                value={date}
                onChange={(e) => setDate(e.target.value)}
                className="w-[160px] h-9 text-sm shadow-sm"
              />
              {sudahDitutup && (
                <span className="inline-flex items-center gap-1.5 text-xs font-medium text-emerald-700 bg-emerald-50 border border-emerald-200 rounded-full px-3 py-1">
                  <Check className="w-3.5 h-3.5" /> Sesi sudah ditutup
                </span>
              )}
            </div>

            {/* LANGKAH 1 — BUKA SESI */}
            {!sudahDibuka && (
              <div className="space-y-6">
                <div className="flex items-start gap-3 bg-primary/5 border border-primary/20 rounded-xl p-5">
                  <Wallet className="w-5 h-5 text-primary shrink-0 mt-0.5" />
                  <div>
                    <h3 className="font-medium text-foreground">
                      Buka Sesi Kasir
                    </h3>
                    <p className="text-sm text-muted-foreground mt-1 leading-relaxed">
                      Masukkan <strong>uang awal (float)</strong> yang ditaruh
                      di laci sebelum sesi dimulai. Uang ini digunakan untuk
                      memberi kembalian tunai kepada pelanggan.
                    </p>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label
                      htmlFor="awal"
                      className="font-medium text-foreground"
                    >
                      Uang Awal Sesi (Rp)
                    </label>
                    <div className="relative">
                      <span className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground font-medium">
                        Rp
                      </span>
                      <Input
                        id="awal"
                        type="number"
                        placeholder="Contoh: 200000"
                        value={uangAwal}
                        onChange={(e) =>
                          setUangAwal(
                            e.target.value === "" ? "" : e.target.value,
                          )
                        }
                        className="pl-12 h-14 text-2xl font-semibold tabular-nums shadow-sm"
                      />
                    </div>
                    <p className="text-xs text-muted-foreground">
                      Contoh: uang awal 200.000 → di akhir hari laci berisi
                      1.200.000 → penambahan hari ini = 1.000.000.
                    </p>
                  </div>

                  {error && (
                    <div className="flex items-center gap-2 p-3 bg-destructive/10 text-destructive text-sm rounded-md border border-destructive/20">
                      <AlertCircle className="w-4 h-4 shrink-0" />
                      {error}
                    </div>
                  )}
                  {success && (
                    <div className="flex items-center gap-2 p-3 bg-emerald-50 text-emerald-700 text-sm rounded-md border border-emerald-100">
                      <Check className="w-4 h-4 shrink-0" />
                      {success}
                    </div>
                  )}

                  <div className="pt-2 flex flex-col sm:flex-row justify-end gap-3 border-t border-border/50">
                    <Button
                      onClick={handleBukaSesi}
                      disabled={submitting || uangAwal === ""}
                      className="h-11 px-8 rounded-full bg-primary hover:bg-primary/90 text-primary-foreground shadow-sm font-medium"
                    >
                      {submitting ? (
                        <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                      ) : (
                        <Wallet className="w-4 h-4 mr-2" />
                      )}
                      Buka Sesi Kasir
                    </Button>
                  </div>
                </div>
              </div>
            )}

            {sudahDibuka && (
              <div className="flex flex-col items-center justify-center p-12 text-center bg-muted/20 border border-border/50 rounded-2xl">
                <Check className="w-12 h-12 text-emerald-500 mb-4" />
                <h3 className="text-xl font-medium text-foreground">
                  Kasir Sudah Dibuka
                </h3>
                <p className="text-muted-foreground mt-2 max-w-md">
                  Sesi kasir untuk hari ini telah berhasil dibuka. Silakan
                  menuju halaman <strong>Tutup Kasir</strong> di penghujung hari
                  untuk mengakhiri sesi.
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    </>
  );
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { revalidatePath } from "next/cache";
import { logActivity, buildDeskripsi } from "@/lib/activity-log";

async function requireAuth() {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return false;
  const { data: pengguna } = await supabase
    .from("pengguna")
    .select("level")
    .eq("username", user.email?.split("@")[0])
    .single();
  return pengguna?.level === "ADMIN" || pengguna?.level === "OWNER";
}

export async function addCustomer(data: {
  nama_pelanggan: string;
  alamat?: string | null;
  no_hp?: string | null;
  email?: string | null;
  keterangan?: string | null;
}) {
  const ok = await requireAuth();
  if (!ok) return { error: "Unauthorized" };

  const supabase = await createClient();
  const { error } = await supabase.from("pelanggan").insert([data]);

  if (error) {
    console.error("Failed to add customer:", error);
    return { error: "Gagal menambah pelanggan" };
  }

  await logActivity(supabase, {
    aksi: "CREATE",
    entitas: "pelanggan",
    deskripsi: buildDeskripsi({ aksi: "CREATE", entitas: "pelanggan", data_baru: data as unknown as Record<string, unknown> }),
    data_baru: data as unknown as Record<string, unknown>,
  });

  revalidatePath("/dashboard/customers");
  return { success: true };
}

export async function updateCustomer(id: number, data: {
  nama_pelanggan: string;
  alamat?: string | null;
  no_hp?: string | null;
  email?: string | null;
  keterangan?: string | null;
  point?: number | null;
}) {
  const ok = await requireAuth();
  if (!ok) return { error: "Unauthorized" };

  const supabase = await createClient();

  const { data: oldCustomer } = await supabase
    .from("pelanggan")
    .select("nama_pelanggan, alamat, no_hp, email, keterangan")
    .eq("id", id)
    .single();

  const { error } = await supabase.from("pelanggan").update(data).eq("id", id);
  if (error) {
    console.error("Failed to update customer:", error);
    return { error: "Gagal memperbarui pelanggan" };
  }

  await logActivity(supabase, {
    aksi: "UPDATE",
    entitas: "pelanggan",
    id_entitas: id,
    deskripsi: buildDeskripsi({ aksi: "UPDATE", entitas: "pelanggan", id_entitas: id, data_lama: oldCustomer ? (oldCustomer as unknown as Record<string, unknown>) : null, data_baru: data as unknown as Record<string, unknown> }),
    data_lama: oldCustomer ? (oldCustomer as unknown as Record<string, unknown>) : null,
    data_baru: data as unknown as Record<string, unknown>,
  });

  revalidatePath("/dashboard/customers");
  return { success: true };
}

export async function deleteCustomer(id: number, name: string) {
  const ok = await requireAuth();
  if (!ok) return { error: "Unauthorized" };

  if (name.toUpperCase() === "UMUM") {
    return { error: "Pelanggan UMUM tidak dapat dihapus" };
  }

  const supabase = await createClient();

  const { data: oldCustomer } = await supabase
    .from("pelanggan")
    .select("nama_pelanggan, no_hp")
    .eq("id", id)
    .single();

  const { error } = await supabase.from("pelanggan").delete().eq("id", id);
  if (error) {
    console.error("Failed to delete customer:", error);
    return { error: "Gagal menghapus pelanggan" };
  }

  await logActivity(supabase, {
    aksi: "DELETE",
    entitas: "pelanggan",
    id_entitas: id,
    deskripsi: buildDeskripsi({ aksi: "DELETE", entitas: "pelanggan", id_entitas: id, data_lama: oldCustomer ? (oldCustomer as unknown as Record<string, unknown>) : null }),
    data_lama: oldCustomer ? (oldCustomer as unknown as Record<string, unknown>) : null,
  });

  revalidatePath("/dashboard/customers");
  return { success: true };
}

export async function importCustomers(
  rows: Record<string, string>[]
) {
  const ok = await requireAuth();
  if (!ok) return { error: "Unauthorized" };

  if (!rows || rows.length === 0) {
    return { error: "Data impor kosong" };
  }

  const supabase = await createClient();

  const payload = rows.map((r) => ({
    nama_pelanggan: r["Nama Pelanggan"] || r["nama_pelanggan"] || "",
    alamat: r["Alamat"] || r["alamat"] || null,
    no_hp: r["No HP"] || r["No. HP"] || r["no_hp"] || r["Telepon"] || null,
    email: r["Email"] || r["email"] || null,
    keterangan: r["Keterangan"] || r["keterangan"] || null,
  })).filter((item) => item.nama_pelanggan.trim() !== "");

  if (payload.length === 0) {
    return { error: "Tidak ada baris data pelanggan yang valid (Nama Pelanggan wajib)" };
  }

  const { data: inserted, error } = await supabase
    .from("pelanggan")
    .insert(payload)
    .select("id");

  if (error) {
    console.error("Failed to import customers:", error);
    return { error: "Gagal menyimpan data pelanggan: " + error.message };
  }

  await logActivity(supabase, {
    aksi: "CREATE",
    entitas: "pelanggan",
    deskripsi: `Bulk import ${payload.length} pelanggan`,
    data_baru: { count: payload.length },
  });

  revalidatePath("/dashboard/customers");
  return { success: true, count: payload.length, message: `Berhasil mengimpor ${payload.length} data pelanggan.` };
}

"use client";

import { useState, useMemo, useTransition, useDeferredValue } from "react";
import { Plus, Trash2, Users, X, AlertCircle, Check, Loader2, Edit2, Upload } from "lucide-react";
import { useTable } from "@/hooks/use-table";
import DataTable, { type Column, type DeleteModalConfig } from "@/components/data-table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { TableCell } from "@/components/ui/table";
import { addCustomer, updateCustomer, deleteCustomer, importCustomers } from "./actions";
import { exportToCSV, exportToPDF } from "@/lib/export-utils";
import ImportCSVModal from "@/components/import-csv-modal";
import { ExportDropdown } from "@/components/export-dropdown";

interface Customer {
  id: number;
  nama_pelanggan: string;
  alamat: string | null;
  no_hp: string | null;
  email: string | null;
  keterangan: string | null;
  created_at: string;
  point: number;
}

export default function CustomersClient({ initialCustomers }: { initialCustomers: Customer[] }) {
  const [searchQuery, setSearchQuery] = useState("");
  const deferredSearchQuery = useDeferredValue(searchQuery);
  const [isImportOpen, setIsImportOpen] = useState(false);

  const [isPending, startTransition] = useTransition();

  const [editingId, setEditingId] = useState<number | 'new' | null>(null);
  const [editForm, setEditForm] = useState<Partial<Customer>>({});

  const [deleteTarget, setDeleteTarget] = useState<Customer | null>(null);
  const [errorMsg, setErrorMsg] = useState("");

  const filteredData = useMemo(() => {
    let result = [...initialCustomers];

    if (deferredSearchQuery.trim()) {
      const q = deferredSearchQuery.toLowerCase();
      result = result.filter(
        (c) =>
          c.nama_pelanggan.toLowerCase().includes(q) ||
          c.no_hp?.toLowerCase().includes(q) ||
          c.email?.toLowerCase().includes(q) ||
          c.alamat?.toLowerCase().includes(q) ||
          String(c.point ?? 0).includes(q)
      );
    }

    return result;
  }, [initialCustomers, deferredSearchQuery]);

  const table = useTable({ data: filteredData, defaultItemsPerPage: 25 });

  const handleSaveInline = () => {
    if (!editForm.nama_pelanggan?.trim()) {
      setErrorMsg("Nama pelanggan wajib diisi");
      return;
    }
    setErrorMsg("");

    const data = {
      nama_pelanggan: editForm.nama_pelanggan,
      alamat: editForm.alamat || null,
      no_hp: editForm.no_hp || null,
      email: editForm.email || null,
      keterangan: editForm.keterangan || null,
    };

    startTransition(async () => {
      const result = editingId === "new"
        ? await addCustomer(data as Parameters<typeof addCustomer>[0])
        : await updateCustomer(editingId as number, data);

      if (result.error) {
        setErrorMsg(result.error);
      } else {
        setEditingId(null);
        setEditForm({});
      }
    });
  };

  const handleDeleteConfirm = async () => {
    if (!deleteTarget) return;
    setErrorMsg("");
    startTransition(async () => {
      const result = await deleteCustomer(deleteTarget.id, deleteTarget.nama_pelanggan);
      if (result.error) {
        setErrorMsg(result.error);
      } else {
        setDeleteTarget(null);
      }
    });
  };

  const handleEditClick = (e: React.MouseEvent, customer: Customer) => {
    e.stopPropagation();
    if (customer.nama_pelanggan?.toUpperCase() === "UMUM") return;
    setEditingId(customer.id);
    setEditForm(customer);
    setErrorMsg("");
  };

  const handleCancelInline = () => {
    setEditingId(null);
    setEditForm({});
    setErrorMsg("");
  };

  const handleExportCSV = () => {
    // Header SAMA dengan template import pelanggan (urutan: Nama, Alamat, No. HP,
    // Email, Keterangan) agar bisa round-trip; kolom Poin diletakkan di akhir
    // (tidak dibaca import, hanya informasi tambahan).
    const headers = ["Nama Pelanggan", "Alamat", "No. HP", "Email", "Keterangan", "Poin"];
    const data = filteredData.map(c => [
      c.nama_pelanggan,
      c.alamat || "",
      c.no_hp || "",
      c.email || "",
      c.keterangan || "",
      String(c.point ?? 0)
    ]);
    exportToCSV("Data_Pelanggan", headers, data);
  };

  const handleExportPDF = () => {
    const headers = ["Nama Pelanggan", "No. HP", "Email", "Alamat", "Keterangan", "Poin"];
    const data = filteredData.map(c => [
      c.nama_pelanggan,
      c.no_hp || "-",
      c.email || "-",
      c.alamat || "-",
      c.keterangan || "-",
      String(c.point ?? 0)
    ]);
    exportToPDF("Data_Pelanggan", "Laporan Data Pelanggan", headers, data);
  };

  const editInput = (field: keyof Customer, placeholder: string, opts?: { tabular?: boolean }) => (
    <Input
      aria-label={placeholder}
      placeholder={placeholder}
      value={String(editForm[field] ?? "")}
      onChange={(e) => setEditForm(prev => ({ ...prev, [field]: e.target.value }))}
      className={`h-8 text-[13px] ${opts?.tabular ? "tabular-nums" : ""}`}
    />
  );

  const columns: Column<Customer>[] = [
    { key: "nama_pelanggan", header: "Nama", sortable: true, className: "pl-6", headerClassName: "pl-6" },
    { key: "no_hp", header: "No. HP", sortable: true, render: (c) => <span className="tabular-nums">{c.no_hp || "-"}</span> },
    { key: "point", header: "Poin", sortable: true, className: "w-[80px]", headerClassName: "w-[80px]", render: (c) => <span className="tabular-nums font-medium">{c.point ?? 0}</span> },
    { key: "email", header: "Email", sortable: true },
    { key: "alamat", header: "Alamat", sortable: true, render: (c) => <span className="max-w-xs truncate block">{c.alamat || "-"}</span> },
    { key: "keterangan", header: "Keterangan", sortable: true, render: (c) => <span className="max-w-xs truncate block">{c.keterangan || "-"}</span> },
    {
      key: "actions", header: "", className: "pr-6", headerClassName: "w-[100px] pr-6",
      render: (customer) => {
        const isUmum = customer.nama_pelanggan?.toUpperCase() === "UMUM";
        if (isUmum) return null;
        return (
          <div className="flex justify-end gap-1">
            <Button variant="outline" size="icon" aria-label="Edit customer" className="h-11 w-11 md:h-8 md:w-8 md:border-transparent md:bg-transparent text-muted-foreground hover:text-foreground" onClick={(e) => handleEditClick(e, customer)} disabled={editingId !== null}>
              <Edit2 className="h-4 w-4" />
            </Button>
            <Button variant="outline" size="icon" aria-label="Hapus customer" className="h-11 w-11 md:h-8 md:w-8 md:border-transparent md:bg-transparent text-muted-foreground hover:text-destructive hover:bg-destructive/10" onClick={(e) => { e.stopPropagation(); setDeleteTarget(customer); }} disabled={editingId !== null}>
              <Trash2 className="h-4 w-4" />
            </Button>
          </div>
        );
      },
    },
  ];

  const deleteModal: DeleteModalConfig | undefined = deleteTarget ? {
    open: true,
    title: "Hapus Pelanggan?",
    itemName: deleteTarget.nama_pelanggan,
    onConfirm: handleDeleteConfirm,
    onCancel: () => { setDeleteTarget(null); setErrorMsg(""); },
    isPending,
    error: errorMsg,
  } : undefined;

  return (
    <>
      <DataTable
      data={table.paginatedData}
      total={table.total}
      columns={columns}
      rowKey={(c) => c.id}
      search={searchQuery}
      onSearchChange={setSearchQuery}
      searchPlaceholder="Cari nama, telp, atau alamat..."
      sortConfig={table.sortConfig}
      onSort={table.handleSort}
      currentPage={table.currentPage}
      onPageChange={table.setCurrentPage}
      itemsPerPage={table.itemsPerPage}
      onItemsPerPageChange={table.setItemsPerPage}
      editingId={editingId as number | "new" | null}
      renderEditRow={() => {
        return (
