            <TableCell className="align-top pt-4">{editInput("alamat", "Alamat")}</TableCell>
            <TableCell className="align-top pt-4">{editInput("keterangan", "Keterangan")}</TableCell>
            <TableCell className="pr-6 align-top pt-4 text-right">
