            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { generateLabaRugi } from "@/lib/laporan-keuangan";

export async function fetchLabaRugi(startDate: string, endDate: string) {
  const supabase = await createClient();

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return { error: "Unauthorized" };

  const role = user.user_metadata?.role;
  if (role !== "OWNER" && role !== "ADMIN") {
    return { error: "Forbidden" };
  }

  try {
    const data = await generateLabaRugi(supabase, startDate, endDate);
    return { data };
  } catch (err: any) {
    return { error: "Gagal menghasilkan laporan Laba Rugi" };
  }
}

"use client";

import { useState } from "react";
import { format } from "date-fns";
import { Printer, Search, Loader2, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { fetchLabaRugi } from "./actions";
import { exportToCSV } from "@/lib/export-utils";
import { ExportDropdown } from "@/components/export-dropdown";
import { terbilangRupiah } from "@/lib/terbilang";
import type { StoreSettings } from "@/lib/store-settings";

function formatIDR(n: number) {
  return new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n);
}

export default function LabaRugiClient({ initialData, store }: { initialData: any; store?: StoreSettings | null }) {
  const [start, setStart] = useState(initialData?.periode?.start || "");
  const [end, setEnd] = useState(initialData?.periode?.end || "");
  const [data, setData] = useState(initialData);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleFetch = async () => {
    setLoading(true);
    setError("");
    const res = await fetchLabaRugi(start, end);
    if (res.data) {
      setData(res.data);
    } else {
      setError(res.error || "Laporan tidak dapat dimuat. Silakan coba lagi.");
    }
    setLoading(false);
  };

  const handleExport = () => {
    if (!data) return;
    const headers = ["Kategori", "Item", "Jumlah"];
    const rows: Array<[string, string, number]> = [
      ["PENDAPATAN", "Penjualan Kotor", data.pendapatan.penjualan_kotor],
      ["PENDAPATAN", "Diskon Penjualan (-)", data.pendapatan.diskon],
      ["PENDAPATAN", "Total Pendapatan Bersih", data.pendapatan.pendapatan_bersih],
      ["BIAYA", "Total HPP / Beban Pokok (-)", data.biaya.hpp],
      ["HASIL", "Laba Kotor", data.hasil.laba_kotor],
    ];

    // Beban per kategori
    if (data.biaya.beban && data.biaya.beban.length > 0) {
      for (const b of data.biaya.beban) {
        rows.push(["BEBAN", b.nama, b.jumlah]);
      }
    }
    rows.push(["BEBAN", "Total Beban Operasional (-)", data.hasil.beban_operasional]);

    // Penyesuaian
    if (data.penyesuaian) {
      if (data.penyesuaian.selisih_kas !== 0) {
        rows.push(["PENYESUAIAN", "Selisih Kas", data.penyesuaian.selisih_kas]);
      }
      if (data.penyesuaian.koreksi_stok !== 0) {
        rows.push(["PENYESUAIAN", "Koreksi / Selisih Stok", data.penyesuaian.koreksi_stok]);
      }
    }

    rows.push(["HASIL", "Laba / Rugi Bersih", data.hasil.laba_bersih]);
    exportToCSV(`laba-rugi-${start}-to-${end}`, headers, rows);
  };

  return (
    <div className="flex-1 flex flex-col min-h-0 bg-background border border-border rounded-[12px] shadow-[0_1px_3px_rgba(0,55,112,0.08)] overflow-hidden relative w-full print-area print:border-none print:shadow-none print:bg-transparent">
      <div className="shrink-0 flex flex-col items-start xl:flex-row xl:items-center justify-between p-4 lg:p-6 border-b border-border bg-transparent gap-4 print:hidden">
        <div className="flex-1 flex flex-col xl:flex-row items-stretch xl:items-center gap-3 w-full">
          <div className="flex flex-col xl:flex-row items-stretch xl:items-center gap-2 bg-muted/50 p-1 rounded-lg border border-border w-full xl:w-auto">
            <div className="flex items-center justify-between sm:justify-start gap-2 px-2 py-1 xl:py-0">
              <Label htmlFor="start" className="text-[11px] uppercase tracking-wider text-muted-foreground whitespace-nowrap">Tanggal Mulai</Label>
              <Input id="start" type="date" value={start} onChange={(e) => setStart(e.target.value)} className="w-full sm:w-[150px] h-9 text-sm bg-background" />
            </div>
