"use client";

import { useState, useEffect, useMemo } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Search, Loader2, PackageOpen, CheckSquare, Square, Filter, X } from "lucide-react";
import { createClient } from "@/lib/supabase/client";
import { fetchAllRows } from "@/lib/supabase/fetch-all";
import { cn } from "@/lib/utils";
import { Select } from "@/components/ui/select";

export interface PrintProduct {
  id: number;
  nama_produk: string;
  barcode: string;
  harga_jual_satuan: number;
  sku: string;
  harga_modal: number;
  id_merk: number | null;
  id_lokasi_area: number | null;
}

interface ProductSelectorModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onInsert: (selected: PrintProduct[]) => void;
}

export function ProductSelectorModal({ open, onOpenChange, onInsert }: ProductSelectorModalProps) {
  const [search, setSearch] = useState("");
  const [products, setProducts] = useState<PrintProduct[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set());

  // Filter state
  const [merkFilter, setMerkFilter] = useState("all");
  const [lokasiFilter, setLokasiFilter] = useState("all");
  const [merks, setMerks] = useState<{ id: number; nama: string }[]>([]);
  const [lokasiAreas, setLokasiAreas] = useState<{ id: number; nama: string }[]>([]);

  useEffect(() => {
    if (open) {
      fetchProducts("");
      fetchRefData();
      setSelectedIds(new Set());
      setSearch("");
      setMerkFilter("all");
      setLokasiFilter("all");
    }
  }, [open]);

  const fetchRefData = async () => {
    const supabase = createClient();
    const [merksRes, lokasiRes] = await Promise.all([
      supabase.from("merk").select("id, nama").order("nama"),
      supabase.from("lokasi_area").select("id, nama").order("nama"),
    ]);
    setMerks(merksRes.data || []);
    setLokasiAreas(lokasiRes.data || []);
  };

  const fetchProducts = async (query: string) => {
    setLoading(true);
    const supabase = createClient();

    try {
      const data = await fetchAllRows<PrintProduct>(supabase, (db, from, to) => {
        let q = db
          .from("produk")
          .select("id, nama_produk, barcode, harga_jual_satuan, sku, harga_modal, id_merk, id_lokasi_area")
          .order("nama_produk", { ascending: true })
          .range(from, to);
        if (query) {
          q = q.ilike("nama_produk", `%${query}%`);
        }
        return q;
      });
      setProducts(data);
    } catch (e) {
      console.error("Gagal memuat produk:", e);
      setProducts([]);
    }
    setLoading(false);
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    fetchProducts(search);
  };

  // Filter produk: hanya yang harga_jual_satuan > 0 + filter merk & lokasi
  const filteredProducts = useMemo(() => {
    return products.filter((p) => {
      // Hanya produk dengan harga retail > 0
      if (!p.harga_jual_satuan || p.harga_jual_satuan <= 0) return false;
      // Filter merk
      if (merkFilter !== "all") {
        if (merkFilter === "none") {
          if (p.id_merk != null) return false;
        } else {
          if (p.id_merk?.toString() !== merkFilter) return false;
        }
      }
      // Filter lokasi
      if (lokasiFilter !== "all") {
        if (lokasiFilter === "none") {
          if (p.id_lokasi_area != null) return false;
        } else {
          if (p.id_lokasi_area?.toString() !== lokasiFilter) return false;
        }
      }
      return true;
    });
  }, [products, merkFilter, lokasiFilter]);

  const hasFilters = merkFilter !== "all" || lokasiFilter !== "all";

  const allSelected = filteredProducts.length > 0 && filteredProducts.every(p => selectedIds.has(p.id));

  const toggleSelectAll = () => {
    if (filteredProducts.length === 0) return;
    const newSet = new Set(selectedIds);
    if (allSelected) {
      // Uncheck all currently visible products
      filteredProducts.forEach(p => newSet.delete(p.id));
    } else {
      // Check all currently visible products (merge with existing)
      filteredProducts.forEach(p => newSet.add(p.id));
    }
    setSelectedIds(newSet);
  };

  const toggleSelect = (id: number) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedIds(newSet);
  };

  const handleInsert = () => {
    const selectedProducts = products.filter(p => selectedIds.has(p.id));
    onInsert(selectedProducts);
    onOpenChange(false);
  };

  const clearFilters = () => {
    setMerkFilter("all");
    setLokasiFilter("all");
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[95vw] lg:max-w-6xl h-[90vh] flex flex-col p-0 gap-0 overflow-hidden bg-background">

        {/* Header Section */}
        <div className="flex flex-col border-b border-border bg-muted/20">
          <DialogHeader className="px-4 sm:px-6 py-5 pb-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                <PackageOpen className="w-5 h-5 text-primary" />
              </div>
              <div>
                <DialogTitle className="text-xl">Pilih Produk</DialogTitle>
                <DialogDescription>
                  Pilih produk yang memiliki harga retail untuk antrean cetak label.
                </DialogDescription>
              </div>
            </div>
          </DialogHeader>

          {/* Search + Filters */}
          <div className="px-4 sm:px-6 pb-4 space-y-3">
            <form onSubmit={handleSearch} className="flex gap-3">
              <div className="relative flex-1">
                <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
                <Input 
                  placeholder="Ketik nama produk lalu tekan enter..." 
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="pl-11 h-12 text-base rounded-xl bg-background border-border shadow-sm focus-visible:ring-primary/20"
                />
              </div>
              <Button type="submit" disabled={loading} size="lg" className="h-12 px-8 rounded-xl">
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : "Cari"}
              </Button>
            </form>

            {/* Filter Row */}
            <div className="flex flex-wrap items-center gap-3">
              <div className="flex items-center gap-2 text-xs text-muted-foreground">
                <Filter className="w-3.5 h-3.5" />
                <span>Filter:</span>
              </div>

              <Select value={merkFilter} onChange={(e) => setMerkFilter(e.target.value)} className="w-[160px] h-9 text-sm rounded-lg">
                <option value="all">Semua Merk</option>
                {merks.map((m) => (
                  <option key={m.id} value={m.id.toString()}>{m.nama}</option>
                ))}
                <option value="none">Tanpa Merk</option>
              </Select>

              <Select value={lokasiFilter} onChange={(e) => setLokasiFilter(e.target.value)} className="w-[160px] h-9 text-sm rounded-lg">
                <option value="all">Semua Lokasi</option>
                {lokasiAreas.map((l) => (
                  <option key={l.id} value={l.id.toString()}>{l.nama}</option>
                ))}
                <option value="none">Tanpa Lokasi</option>
              </Select>

              {hasFilters && (
                <Button variant="ghost" size="sm" onClick={clearFilters} className="text-xs text-muted-foreground hover:text-foreground gap-1">
                  <X className="w-3 h-3" />
                  Reset
                </Button>
              )}

              <span className="text-xs text-muted-foreground ml-auto">
                {filteredProducts.length} produk dengan harga retail
              </span>
            </div>
          </div>
        </div>

        {/* Content Section (Table) */}
        <div className="flex-1 overflow-y-auto relative bg-background">
          {loading && products.length === 0 && (
            <div className="absolute inset-0 flex items-center justify-center bg-background/50 z-10 backdrop-blur-sm">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="w-8 h-8 animate-spin text-primary" />
                <p className="text-sm text-muted-foreground">Memuat data produk...</p>
              </div>
            </div>
          )}

          <table className="w-full text-sm text-left">
            <thead className="text-xs text-muted-foreground uppercase bg-muted/50 sticky top-0 z-10 backdrop-blur-md">
              <tr>
                <th className="px-3 sm:px-6 py-4 w-16">
                  <button 
                    onClick={toggleSelectAll}
                    disabled={filteredProducts.length === 0}
                    className="flex items-center justify-center w-full h-full text-muted-foreground hover:text-foreground transition-colors disabled:opacity-50"
                  >
                    {allSelected ? (
                      <CheckSquare className="w-5 h-5 text-primary" />
                    ) : (
                      <Square className="w-5 h-5" />
                    )}
                  </button>
                </th>
                <th className="px-3 sm:px-4 py-4 font-semibold tracking-wider">Nama Produk</th>
                <th className="px-3 sm:px-4 py-4 font-semibold tracking-wider">Barcode</th>
                <th className="px-3 sm:px-6 py-4 font-semibold tracking-wider text-right">Harga Jual</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {filteredProducts.length === 0 && !loading && (
                <tr>
                  <td colSpan={4} className="px-4 py-16">
                    <div className="flex flex-col items-center justify-center text-center">
                      <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mb-4">
                        <Search className="w-8 h-8 text-muted-foreground/50" />
                      </div>
                      <p className="text-base font-medium text-foreground">Tidak ada produk ditemukan</p>
                      <p className="text-sm text-muted-foreground mt-1">
                        {products.length > 0 && !hasFilters
                          ? "Tidak ada produk dengan harga retail > 0."
                          : "Coba ubah filter atau kata kunci pencarian."}
                      </p>
                    </div>
                  </td>
                </tr>
              )}
              {filteredProducts.map((product) => {
                const isSelected = selectedIds.has(product.id);
                return (
                  <tr 
                    key={product.id} 
                    className={cn(
                      "hover:bg-muted/40 cursor-pointer transition-colors group",
                      isSelected && "bg-primary/5 hover:bg-primary/10"
                    )}
                    onClick={() => toggleSelect(product.id)}
                  >
                    <td className="px-3 sm:px-6 py-4 text-center">
                      <button 
                        className={cn(
                          "transition-colors",
                          isSelected ? "text-primary" : "text-muted-foreground group-hover:text-foreground"
                        )}
                        onClick={(e) => {
                          e.stopPropagation();
                          toggleSelect(product.id);
                        }}
                      >
                        {isSelected ? (
                          <CheckSquare className="w-5 h-5" />
                        ) : (
                          <Square className="w-5 h-5" />
                        )}
                      </button>
                    </td>
                    <td className="px-3 sm:px-4 py-4">
                      <span className={cn("font-medium text-base", isSelected ? "text-foreground" : "text-foreground/90")}>
                        {product.nama_produk}
                      </span>
                    </td>
                    <td className="px-3 sm:px-4 py-4">
                      {product.barcode ? (
                        <span className="font-mono text-xs bg-muted px-2 py-1 rounded-md text-muted-foreground">
                          {product.barcode}
                        </span>
                      ) : (
                        <span className="text-xs text-muted-foreground/50 italic">Kosong</span>
                      )}
                    </td>
                    <td className="px-3 sm:px-6 py-4 text-right">
                      <span className="font-medium text-foreground">
                        {new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(product.harga_jual_satuan)}
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        {/* Footer Section */}
        <div className="border-t border-border bg-background p-4 sm:p-5 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <div className="flex flex-col sm:flex-row sm:items-center gap-3">
            <div className="bg-primary/10 text-primary px-4 py-2 rounded-lg text-sm font-medium text-center whitespace-nowrap">
              {selectedIds.size} Produk Terpilih
            </div>
            {selectedIds.size > 0 && (
              <Button variant="ghost" size="sm" onClick={() => setSelectedIds(new Set())} className="text-muted-foreground hover:text-foreground">
                Hapus Semua Pilihan
              </Button>
            )}
          </div>
          <div className="flex flex-col sm:flex-row gap-3 w-full sm:w-auto">
            <Button variant="outline" size="lg" onClick={() => onOpenChange(false)} className="px-4 sm:px-8 rounded-xl w-full sm:w-auto">
              Batal
            </Button>
            <Button size="lg" onClick={handleInsert} disabled={selectedIds.size === 0} className="px-4 sm:px-8 rounded-xl shadow-sm w-full sm:w-auto">
              Masukkan ke Antrean
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { Save, Check, AlertCircle, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { saveFinanceSettings } from "./actions";

export default function FinanceSettingsForm({ initialData }: { initialData: any }) {
  const [modalAwal, setModalAwal] = useState(initialData?.modal_awal || 0);
  const [tanggalMulai, setTanggalMulai] = useState(initialData?.tanggal_mulai || new Date().toISOString().slice(0, 10));
  const [namaPemilik, setNamaPemilik] = useState(initialData?.nama_pemilik || "");
  const [npwp, setNpwp] = useState(initialData?.npwp || "");

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    setSuccess(false);

    const res = await saveFinanceSettings({
      modal_awal: Number(modalAwal),
      tanggal_mulai: tanggalMulai,
      nama_pemilik: namaPemilik,
      npwp: npwp,
    });

    if (res?.error) {
      setError(res.error);
    } else {
      setSuccess(true);
      setTimeout(() => setSuccess(false), 3000);
    }
    setLoading(false);
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="modal_awal">Modal Awal (Saldo Awal Kas)</Label>
          <div className="relative">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground font-medium">Rp</span>
            <Input 
              id="modal_awal" 
              type="number" 
              value={modalAwal} 
              onChange={(e) => setModalAwal(Number(e.target.value))} 
              className="pl-10"
              required
            />
          </div>
          <p className="text-[10px] text-muted-foreground italic">Saldo kas saat pertama kali menggunakan sistem ini.</p>
        </div>

        <div className="space-y-2">
          <Label htmlFor="tanggal_mulai">Tanggal Mulai Usaha / Sistem</Label>
          <Input 
            id="tanggal_mulai" 
            type="date" 
            value={tanggalMulai} 
            onChange={(e) => setTanggalMulai(e.target.value)} 
            required
          />
        </div>

        <div className="pt-4 border-t border-border">
          <h4 className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-4">Informasi Identitas (Opsional)</h4>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="nama_pemilik">Nama Pemilik</Label>
              <Input 
                id="nama_pemilik" 
                value={namaPemilik} 
                onChange={(e) => setNamaPemilik(e.target.value)} 
                placeholder="Contoh: Budi Santoso"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="npwp">NPWP</Label>
              <Input 
                id="npwp" 
                value={npwp} 
                onChange={(e) => setNpwp(e.target.value)} 
                placeholder="00.000.000.0-000.000"
              />
            </div>
          </div>
        </div>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 bg-destructive/10 text-destructive text-sm rounded-md">
          <AlertCircle className="w-4 h-4 shrink-0" />
          {error}
        </div>
      )}

      {success && (
        <div className="flex items-center gap-2 p-3 bg-emerald-50 text-emerald-700 text-sm rounded-md">
          <Check className="w-4 h-4 shrink-0" />
          Pengaturan berhasil disimpan
        </div>
      )}

      <Button type="submit" className="w-full" disabled={loading}>
        {loading ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
        Simpan Pengaturan
      </Button>
    </form>
  );
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { revalidatePath } from "next/cache";
import { logActivity, buildDeskripsi } from "@/lib/activity-log";

export type ReferenceActionState = {
  success?: boolean;
  error?: string;
  message?: string;
};

// Generic CRUD functions for reference tables (kategori, satuan, metode_bayar)
export async function createReferenceData(
  tableName: "kategori" | "satuan" | "merk" | "metode_bayar" | "lokasi_area",
  prevState: ReferenceActionState,
  formData: FormData
): Promise<ReferenceActionState> {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user || (user.user_metadata?.role !== "ADMIN" && user.user_metadata?.role !== "OWNER")) {
    return { error: "Unauthorized" };
  }

  const nama = formData.get("nama") as string;
  if (!nama || nama.trim() === "") {
    return { error: "Nama tidak boleh kosong" };
  }

  const insertData: Record<string, string> = { nama: nama.trim() };
  if (tableName === "merk") {
    const kode = (formData.get("kode") as string || "").trim();
    if (!kode) return { error: "Kode tidak boleh kosong" };
    insertData.kode = kode;
  }

  const { error: dbError } = await supabase
    .from(tableName)
    .insert(insertData);

  if (dbError) {
    if (dbError.code === "23505") { // Unique violation
      return { error: `Data dengan nama tersebut sudah ada` };
    }
    console.error("Failed to create reference data:", dbError);
    return { error: `Gagal menambah data` };
  }

  await logActivity(supabase, {
    aksi: "CREATE",
    entitas: tableName,
    deskripsi: buildDeskripsi({ aksi: "CREATE", entitas: tableName, data_baru: insertData as unknown as Record<string, unknown> }),
    data_baru: insertData as unknown as Record<string, unknown>,
  });

  revalidatePath("/dashboard/settings/reference-data");
  return { success: true, message: "Data berhasil ditambahkan" };
}

export async function updateReferenceData(
  tableName: "kategori" | "satuan" | "merk" | "metode_bayar" | "lokasi_area",
  prevState: ReferenceActionState,
  formData: FormData
): Promise<ReferenceActionState> {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user || (user.user_metadata?.role !== "ADMIN" && user.user_metadata?.role !== "OWNER")) {
    return { error: "Unauthorized" };
  }

  const id = parseInt(formData.get("id") as string, 10);
  const nama = formData.get("nama") as string;

  if (isNaN(id) || !nama || nama.trim() === "") {
    return { error: "Data tidak valid" };
  }

  const updateData: Record<string, string> = { nama: nama.trim() };
  if (tableName === "merk") {
    const kode = (formData.get("kode") as string || "").trim();
    if (!kode) return { error: "Kode tidak boleh kosong" };
    updateData.kode = kode;
  }

  const { error: dbError } = await supabase
    .from(tableName)
    .update(updateData)
    .eq("id", id);

  if (dbError) {
    if (dbError.code === "23505") { // Unique violation
      return { error: `Data dengan nama tersebut sudah ada` };
    }
    console.error("Failed to update reference data:", dbError);
    return { error: `Gagal memperbarui data` };
  }

  await logActivity(supabase, {
    aksi: "UPDATE",
    entitas: tableName,
    id_entitas: id,
    deskripsi: buildDeskripsi({ aksi: "UPDATE", entitas: tableName, id_entitas: id, data_baru: updateData as unknown as Record<string, unknown> }),
    data_baru: updateData as unknown as Record<string, unknown>,
  });

  revalidatePath("/dashboard/settings/reference-data");
  return { success: true, message: "Data berhasil diperbarui" };
}

export async function deleteReferenceData(
  tableName: "kategori" | "satuan" | "merk" | "metode_bayar" | "lokasi_area",
  id: number
): Promise<ReferenceActionState> {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user || (user.user_metadata?.role !== "ADMIN" && user.user_metadata?.role !== "OWNER")) {
    return { error: "Unauthorized" };
  }

  const { error: dbError } = await supabase
    .from(tableName)
    .delete()
    .eq("id", id);

  if (dbError) {
    if (dbError.code === "23503") { // Foreign key violation
      return { error: `Data tidak dapat dihapus karena masih digunakan` };
    }
    console.error("Failed to delete reference data:", dbError);
    return { error: `Gagal menghapus data` };
  }

  await logActivity(supabase, {
    aksi: "DELETE",
    entitas: tableName,
    id_entitas: id,
    deskripsi: buildDeskripsi({ aksi: "DELETE", entitas: tableName, id_entitas: id }),
  });

  revalidatePath("/dashboard/settings/reference-data");
  return { success: true, message: "Data berhasil dihapus" };
}

export async function importReferenceData(
  tableName: "kategori" | "satuan" | "merk" | "metode_bayar" | "lokasi_area",
  rows: Record<string, string>[]
) {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user || (user.user_metadata?.role !== "ADMIN" && user.user_metadata?.role !== "OWNER")) {
    return { error: "Unauthorized" };
  }

  if (!rows || rows.length === 0) {
    return { error: "Data impor kosong" };
  }

  const payload: any[] = [];

  for (const r of rows) {
    const nama = (r["Nama"] || r["nama"] || r["Nama Kategori"] || r["Nama Satuan"] || r["Nama Merk"] || r["Nama Metode Bayar"] || r["Nama Kategori Produk"] || r["Nama Satuan Barang"] || r["Nama Lokasi Area"] || r["Nama Metode Pembayaran"] || "").trim();
    if (!nama) continue;

    if (tableName === "merk") {
      const kodeRaw = (r["Kode"] || r["kode"] || r["Kode Merk"] || "").trim();
      const kode = kodeRaw || (nama.replace(/[^A-Za-z0-9]/g, "").slice(0, 4).toUpperCase() || "MRK");
      payload.push({ nama, kode });
    } else {
      payload.push({ nama });
    }
  }

  if (payload.length === 0) {
    return { error: "Tidak ada baris data referensi yang valid" };
  }

  const { error: dbError } = await supabase
    .from(tableName)
    .insert(payload);

  if (dbError) {
    console.error(`Failed to import ${tableName}:`, dbError);
    if (dbError.code === "23505") {
      return { error: "Beberapa data dengan Nama/Kode tersebut sudah ada di database" };
    }
    return { error: `Gagal menyimpan data ${tableName}: ${dbError.message}` };
  }

  await logActivity(supabase, {
    aksi: "CREATE",
    entitas: tableName,
    deskripsi: `Bulk import ${payload.length} ${tableName}`,
    data_baru: { count: payload.length },
  });

  revalidatePath("/dashboard/settings/reference-data");
  return { success: true, count: payload.length, message: `Berhasil mengimpor ${payload.length} data ${tableName}.` };
}

