"use client";

import { useState, useMemo, useTransition, useEffect, useDeferredValue } from "react";
import { Plus, Trash2, Edit2, User as UserIcon, Loader2, X, Upload } from "lucide-react";
import { useTable } from "@/hooks/use-table";
import DataTable, { type Column, type DeleteModalConfig } from "@/components/data-table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select } from "@/components/ui/select";
import { TableCell } from "@/components/ui/table";
import { createUser, updateUser, deleteUser, importUsers } from "./actions";
import { exportToCSV, exportToPDF } from "@/lib/export-utils";
import ImportCSVModal from "@/components/import-csv-modal";
import { ExportDropdown } from "@/components/export-dropdown";

type User = {
  id: number;
  username: string;
  nama: string | null;
  level: string;
  aktif: boolean;
  created_at: string;
};

export function UsersClient({ initialUsers }: { initialUsers: User[] }) {
  const [users, setUsers] = useState<User[]>(initialUsers);

  useEffect(() => { setUsers(initialUsers); }, [initialUsers]);

  const [searchQuery, setSearchQuery] = useState("");
  const deferredSearchQuery = useDeferredValue(searchQuery);
  const [isImportOpen, setIsImportOpen] = useState(false);

  const [isPending, startTransition] = useTransition();

  const [editingId, setEditingId] = useState<number | 'new' | null>(null);
  const [editForm, setEditForm] = useState<{
    nama?: string; username?: string; password?: string; level?: string; aktif?: boolean; old_username?: string;
  }>({});

  const [deleteTarget, setDeleteTarget] = useState<User | null>(null);
  const [errorMsg, setErrorMsg] = useState("");

  const handleSaveInline = () => {
    if (!editForm.username?.trim() || !editForm.level || (editingId === 'new' && !editForm.password?.trim())) {
      setErrorMsg("Semua kolom (username, password, level) wajib diisi");
      return;
    }
    setErrorMsg("");
    startTransition(async () => {
      const formData = new FormData();
      formData.append("nama", editForm.nama || "");
      formData.append("username", editForm.username || "");
      formData.append("level", editForm.level || "");
      formData.append("aktif", editForm.aktif ? "true" : "false");
      if (editForm.password) formData.append("password", editForm.password);

      let res;
      if (editingId === 'new') {
        res = await createUser({ success: false }, formData);
      } else {
        formData.append("id", String(editingId));
        formData.append("old_username", editForm.old_username || "");
        res = await updateUser({ success: false }, formData);
      }

      if (res.error) {
        setErrorMsg(res.error);
      } else {
        const newUser: User = {
          id: editingId === 'new' ? Date.now() : (editingId as number),
          nama: editForm.nama || "",
          username: editForm.username || "",
          level: editForm.level || "",
          aktif: editForm.aktif ?? true,
          created_at: new Date().toISOString()
        };
        setUsers(prev => editingId === 'new' ? [...prev, newUser] : prev.map(u => u.id === editingId ? { ...u, ...newUser, created_at: u.created_at } : u));
        setEditingId(null);
        setEditForm({});
      }
    });
  };

  const handleCancelInline = () => {
    setEditingId(null);
    setEditForm({});
    setErrorMsg("");
  };

  const filteredData = useMemo(() => {
    let result = [...users];
    if (deferredSearchQuery.trim()) {
      const q = deferredSearchQuery.toLowerCase();
      result = result.filter((u) =>
        u.username.toLowerCase().includes(q) ||
        u.nama?.toLowerCase().includes(q) ||
        u.level.toLowerCase().includes(q)
      );
    }
    return result;
  }, [users, deferredSearchQuery]);

  const table = useTable({ data: filteredData, defaultItemsPerPage: 25 });

  const handleDeleteConfirm = async () => {
    if (!deleteTarget) return;
    setErrorMsg("");
    startTransition(async () => {
      const res = await deleteUser(deleteTarget.id, deleteTarget.username);
      if (res.error) {
        setErrorMsg(res.error);
      } else {
        setUsers(users.filter((u) => u.id !== deleteTarget.id));
        setDeleteTarget(null);
      }
    });
  };

  const roleOptions = ["KARYAWAN", "KASIR", "ADMIN", "OWNER"];

  const handleExportCSV = () => {
    // Header SAMA dengan template import pengguna agar bisa round-trip.
    // Kolom Password dikosongkan: password asli tersimpan ter-hash di Supabase Auth
    // (kolom pengguna.password = "auth-managed") sehingga TIDAK bisa diexport.
    const headers = ["Username", "Password", "Nama Lengkap", "Level", "Status"];
    const data = filteredData.map(user => [
      user.username,
      "",
      user.nama || user.username,
      user.level,
      user.aktif ? "Aktif" : "Nonaktif"
    ]);
    exportToCSV("Data_Pengguna", headers, data);
  };

  const handleExportPDF = () => {
    const headers = ["Nama", "Username", "Level", "Status", "Tanggal Dibuat"];
    const data = filteredData.map(user => [
      user.nama || user.username,
      user.username,
      user.level,
      user.aktif ? "Aktif" : "Nonaktif",
      new Date(user.created_at).toLocaleString()
    ]);
    exportToPDF("Data_Pengguna", "Laporan Data Pengguna", headers, data);
  };

  const columns: Column<User>[] = [
    {
      key: "nama", header: "Nama", sortable: true, className: "pl-6", headerClassName: "pl-6",
      render: (u) => (
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
            <UserIcon className="w-4 h-4 text-primary" />
          </div>
          {u.nama || u.username}
        </div>
      ),
    },
    { key: "username", header: "Username", sortable: true },
    {
      key: "level", header: "Level", sortable: true,
      render: (u) => (
        <span className={`px-2.5 py-1 text-xs font-medium rounded-full ${
          u.level === "OWNER" ? "bg-purple-100 text-purple-700" :
          u.level === "ADMIN" ? "bg-blue-100 text-blue-700" :
          u.level === "KARYAWAN" ? "bg-slate-100 text-slate-700" :
          "bg-emerald-100 text-emerald-700"
        }`}>
          {u.level}
        </span>
      ),
    },
    {
      key: "aktif", header: "Status", sortable: true,
      render: (u) => (
        <span className={`px-2.5 py-1 text-xs font-medium rounded-full ${u.aktif ? "bg-emerald-100 text-emerald-700" : "bg-destructive/10 text-destructive"}`}>
          {u.aktif ? "Aktif" : "Nonaktif"}
        </span>
      ),
    },
    {
      key: "actions", header: "", className: "pr-6", headerClassName: "w-[100px] pr-6",
      render: (user) => (
        <div className="flex justify-end gap-1">
          <Button variant="ghost" size="icon" aria-label="Edit pengguna" className="h-11 w-11 md:h-8 md:w-8 text-muted-foreground hover:text-foreground"
            onClick={() => {
              setEditingId(user.id);
              setEditForm({
                nama: user.nama || "",
                username: user.username,
                old_username: user.username,
                level: user.level,
                aktif: user.aktif,
                password: ""
              });
              setErrorMsg("");
            }}
          >
            <Edit2 className="h-4 w-4" />
          </Button>
          <Button variant="ghost" size="icon" aria-label="Hapus pengguna" className="h-11 w-11 md:h-8 md:w-8 text-muted-foreground hover:text-destructive hover:bg-destructive/10" onClick={() => setDeleteTarget(user)}>
            <Trash2 className="h-4 w-4" />
          </Button>
        </div>
      ),
    },
  ];

  const deleteModal: DeleteModalConfig | undefined = deleteTarget ? {
    open: true,
    title: "Hapus Pengguna?",
    itemName: deleteTarget.username,
    onConfirm: handleDeleteConfirm,
    onCancel: () => { setDeleteTarget(null); setErrorMsg(""); },
    isPending,
    error: errorMsg,
  } : undefined;

  return (
    <>
      <DataTable
      data={table.paginatedData}
      total={table.total}
      columns={columns}
      rowKey={(u) => u.id}
      search={searchQuery}
      onSearchChange={(v) => { setSearchQuery(v); }}
      searchPlaceholder="Cari pengguna..."
      sortConfig={table.sortConfig}
      onSort={table.handleSort}
      currentPage={table.currentPage}
      onPageChange={table.setCurrentPage}
      itemsPerPage={table.itemsPerPage}
      onItemsPerPageChange={table.setItemsPerPage}
      editingId={editingId as number | "new" | null}
      renderEditRow={(user) => {
        const isNew = user === null;
        return (
          <>
            <TableCell className="pl-6 align-middle py-4 relative">
              <Input autoFocus aria-label="Nama" placeholder="Nama..."
                value={editForm.nama || ""}
                onChange={(e) => setEditForm(prev => ({ ...prev, nama: e.target.value }))}
                className="h-8 min-w-[120px]"
              />
              {errorMsg && <p className="text-[11px] text-destructive mt-1">{errorMsg}</p>}
            </TableCell>
            <TableCell className="align-middle py-4">
              <Input aria-label="Username" placeholder="Username"
                value={editForm.username || ""}
                onChange={(e) => setEditForm(prev => ({ ...prev, username: e.target.value }))}
                className="h-8 min-w-[120px]"
              />
            </TableCell>
            <TableCell className="align-middle py-4">
              <div className="flex items-center gap-2">
                <Select aria-label="Level" value={editForm.level || "KASIR"} onChange={(e) => setEditForm(prev => ({ ...prev, level: e.target.value }))} className="h-8 min-w-[100px] text-xs">
                  {roleOptions.map(role => (
                    <option key={role} value={role}>{role}</option>
                  ))}
                </Select>
                <Input aria-label={isNew ? "Password" : "Password Baru (Kosongkan jika tidak diubah)"} type="password" placeholder="Password..."
                  value={editForm.password || ""}
                  onChange={(e) => setEditForm(prev => ({ ...prev, password: e.target.value }))}
                  className="h-8 min-w-[110px]"
                />
              </div>
            </TableCell>
            <TableCell className="align-middle py-4">
              <div className="flex items-center gap-2 h-8">
                <input type="checkbox" id={isNew ? "aktif_new" : `aktif_${user?.id}`} checked={editForm.aktif ?? true}
                  onChange={(e) => setEditForm(prev => ({ ...prev, aktif: e.target.checked }))}
                  className="w-4 h-4 rounded border-input text-primary focus:ring-primary accent-primary"
                />
                <Label htmlFor={isNew ? "aktif_new" : `aktif_${user?.id}`} className="text-sm">Aktif</Label>
              </div>
            </TableCell>
            <TableCell className="pr-6 align-middle py-4 text-right">
              <div className="flex justify-end gap-1">
                <Button variant="ghost" size="icon" aria-label="Batal Edit" className="h-11 w-11 md:h-8 md:w-8 text-muted-foreground hover:text-foreground" onClick={handleCancelInline} disabled={isPending}>
                  <X className="h-4 w-4" />
                </Button>
                <Button variant="ghost" size="icon" aria-label="Simpan Edit" className="h-11 w-11 md:h-8 md:w-8 text-primary hover:text-primary hover:bg-primary/10" onClick={handleSaveInline} disabled={isPending}>
                  {isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <span className="font-bold">✓</span>}
                </Button>
              </div>
            </TableCell>
          </>
        );
      }}
      actions={[
        { label: "Import CSV", icon: <Upload className="w-4 h-4" />, variant: "outline", onClick: () => setIsImportOpen(true) },
        {
          label: "Export",
          customRender: () => (
            <ExportDropdown
              onExportCSV={handleExportCSV}
              onExportPDF={handleExportPDF}
              className="flex-1 md:flex-none"
            />
          ),
        },
        {
          label: "Pengguna Baru",
          icon: <Plus className="w-4 h-4" />,
          kind: "primary",
          onClick: () => { setEditingId("new"); setEditForm({ level: 'KASIR', aktif: true }); setErrorMsg(""); },
          disabled: editingId !== null,
        },
      ]}
      errorBanner={errorMsg && editingId === 'new' ? errorMsg : null}
      deleteModal={deleteModal}
      emptyState={{
        icon: UserIcon,
        title: "Tidak ada pengguna ditemukan",
        description: "Coba gunakan kata kunci pencarian yang lain.",
      }}
    />
    <ImportCSVModal
      open={isImportOpen}
      onOpenChange={setIsImportOpen}
      title="Import Data Pengguna / Kasir"
      description="Unggah file CSV dengan kolom Username, Password, Nama Lengkap, Level (ADMIN/KASIR/OWNER/KARYAWAN), dan Status (aktif/nonaktif)."
      templateFilename="Template_Import_Pengguna"
      templateHeaders={["Username", "Password", "Nama Lengkap", "Level", "Status"]}
      sampleRows={[
        ["kasir_budi", "password123", "Budi Raharjo", "KASIR", "aktif"],
        ["admin_siti", "adminpass456", "Siti Aminah", "ADMIN", "aktif"],
      ]}
      validateRow={(row) => {
        const username = row["Username"] || row["username"] || "";
        const password = row["Password"] || row["password"] || "";
        if (!username.trim()) return "Username wajib diisi";
        if (!password.trim() || password.trim().length < 6) return "Password minimal 6 karakter";
        return null;
      }}
      onImport={importUsers}
    />
  </>
  );
}

"use client";

import { useState, useMemo, useTransition, useDeferredValue } from "react";
import { Plus, Trash2, Truck, X, AlertCircle, Check, Loader2, Edit2, Upload } from "lucide-react";
import { useTable } from "@/hooks/use-table";
import DataTable, { type Column, type DeleteModalConfig } from "@/components/data-table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { TableCell } from "@/components/ui/table";
import { addSupplier, updateSupplier, deleteSupplier, importSuppliers } from "./actions";
import { exportToCSV, exportToPDF } from "@/lib/export-utils";
import ImportCSVModal from "@/components/import-csv-modal";
import { ExportDropdown } from "@/components/export-dropdown";

interface Supplier {
  id: number;
  nama_supplier: string;
  alamat: string | null;
  telepon: string | null;
  email: string | null;
  keterangan: string | null;
  created_at: string;
}

export default function SuppliersClient({ initialSuppliers }: { initialSuppliers: Supplier[] }) {
  const [searchQuery, setSearchQuery] = useState("");
  const deferredSearchQuery = useDeferredValue(searchQuery);
  const [isImportOpen, setIsImportOpen] = useState(false);

  const [isPending, startTransition] = useTransition();

  const [editingId, setEditingId] = useState<number | 'new' | null>(null);
  const [editForm, setEditForm] = useState<Partial<Supplier>>({});

  const [deleteTarget, setDeleteTarget] = useState<Supplier | null>(null);
  const [errorMsg, setErrorMsg] = useState("");

  const filteredData = useMemo(() => {
    let result = [...initialSuppliers];

    if (deferredSearchQuery.trim()) {
      const q = deferredSearchQuery.toLowerCase();
      result = result.filter(
        (s) =>
          s.nama_supplier.toLowerCase().includes(q) ||
          s.telepon?.toLowerCase().includes(q) ||
          s.email?.toLowerCase().includes(q) ||
          s.alamat?.toLowerCase().includes(q)
      );
    }

    return result;
  }, [initialSuppliers, deferredSearchQuery]);

  const table = useTable({ data: filteredData, defaultItemsPerPage: 25 });

  const handleSaveInline = () => {
    if (!editForm.nama_supplier?.trim()) {
      setErrorMsg("Nama supplier wajib diisi");
      return;
    }
    setErrorMsg("");

    const data = {
      nama_supplier: editForm.nama_supplier ?? "",
      alamat: editForm.alamat || null,
      telepon: editForm.telepon || null,
      email: editForm.email || null,
      keterangan: editForm.keterangan || null,
    };

    startTransition(async () => {
      const result = editingId === "new"
        ? await addSupplier(data)
        : await updateSupplier(editingId as number, data);

      if (result.error) {
        setErrorMsg(result.error);
      } else {
        setEditingId(null);
        setEditForm({});
      }
    });
  };

  const handleDeleteConfirm = async () => {
    if (!deleteTarget) return;
    setErrorMsg("");
    startTransition(async () => {
      const result = await deleteSupplier(deleteTarget.id);
      if (result.error) {
        setErrorMsg(result.error);
      } else {
        setDeleteTarget(null);
      }
    });
  };

  const handleEditClick = (e: React.MouseEvent, supplier: Supplier) => {
    e.stopPropagation();
    setEditingId(supplier.id);
    setEditForm(supplier);
    setErrorMsg("");
  };

  const handleCancelInline = () => {
    setEditingId(null);
    setEditForm({});
    setErrorMsg("");
  };

  const handleExportCSV = () => {
    // Header SAMA dengan template import supplier agar bisa round-trip (export → import ulang)
    const headers = ["Nama Supplier", "Alamat", "No. Telepon", "Email", "Keterangan"];
    const data = filteredData.map(s => [
      s.nama_supplier,
      s.alamat || "",
      s.telepon || "",
      s.email || "",
      s.keterangan || ""
    ]);
    exportToCSV("Data_Supplier", headers, data);
  };

  const handleExportPDF = () => {
    const headers = ["Nama Supplier", "Telepon", "Email", "Alamat", "Keterangan"];
    const data = filteredData.map(s => [
      s.nama_supplier,
      s.telepon || "-",
      s.email || "-",
      s.alamat || "-",
      s.keterangan || "-"
    ]);
    exportToPDF("Data_Supplier", "Laporan Data Supplier", headers, data);
  };

  const editInput = (field: keyof Supplier, placeholder: string, opts?: { tabular?: boolean }) => (
    <Input
      aria-label={placeholder}
      placeholder={placeholder}
      value={String(editForm[field] ?? "")}
      onChange={(e) => setEditForm(prev => ({ ...prev, [field]: e.target.value }))}
      className={`h-8 text-[13px] ${opts?.tabular ? "tabular-nums" : ""}`}
    />
  );

  const columns: Column<Supplier>[] = [
    { key: "nama_supplier", header: "Nama Supplier", sortable: true, className: "pl-6", headerClassName: "pl-6" },
    { key: "telepon", header: "Telepon", sortable: true, render: (s) => <span className="tabular-nums">{s.telepon || "-"}</span> },
    { key: "email", header: "Email", sortable: true },
    { key: "alamat", header: "Alamat", sortable: true, render: (s) => <span className="max-w-xs truncate block">{s.alamat || "-"}</span> },
    { key: "keterangan", header: "Keterangan", sortable: true, render: (s) => <span className="max-w-xs truncate block">{s.keterangan || "-"}</span> },
    {
      key: "actions", header: "", className: "pr-6", headerClassName: "w-[100px] pr-6",
      render: (supplier) => (
        <div className="flex justify-end gap-1">
          <Button variant="outline" size="icon" aria-label="Edit supplier" className="h-11 w-11 md:h-8 md:w-8 md:border-transparent md:bg-transparent text-muted-foreground hover:text-foreground" onClick={(e) => handleEditClick(e, supplier)} disabled={editingId !== null}>
            <Edit2 className="h-4 w-4" />
          </Button>
          <Button variant="outline" size="icon" aria-label="Hapus supplier" className="h-11 w-11 md:h-8 md:w-8 md:border-transparent md:bg-transparent text-muted-foreground hover:text-destructive hover:bg-destructive/10" onClick={(e) => { e.stopPropagation(); setDeleteTarget(supplier); }} disabled={editingId !== null}>
            <Trash2 className="h-4 w-4" />
          </Button>
        </div>
      ),
    },
  ];

  const deleteModal: DeleteModalConfig | undefined = deleteTarget ? {
    open: true,
    title: "Hapus Supplier?",
    itemName: deleteTarget.nama_supplier,
    onConfirm: handleDeleteConfirm,
    onCancel: () => { setDeleteTarget(null); setErrorMsg(""); },
    isPending,
    error: errorMsg,
  } : undefined;

  return (
    <>
      <DataTable
      data={table.paginatedData}
      total={table.total}
      columns={columns}
      rowKey={(s) => s.id}
      search={searchQuery}
      onSearchChange={setSearchQuery}
      searchPlaceholder="Cari supplier, telepon, atau alamat..."
      sortConfig={table.sortConfig}
      onSort={table.handleSort}
      currentPage={table.currentPage}
      onPageChange={table.setCurrentPage}
      itemsPerPage={table.itemsPerPage}
      onItemsPerPageChange={table.setItemsPerPage}
      editingId={editingId as number | "new" | null}
      renderEditRow={() => {
        return (
          <>
            <TableCell className="pl-6 align-top pt-4">
              <Input autoFocus aria-label="Nama Supplier" placeholder="Nama Supplier"
                value={editForm.nama_supplier || ""}
                onChange={(e) => setEditForm(prev => ({ ...prev, nama_supplier: e.target.value }))}
                className="h-8 text-[13px]"
              />
              {errorMsg && <p className="text-[11px] text-destructive mt-1">{errorMsg}</p>}
            </TableCell>
            <TableCell className="align-top pt-4">{editInput("telepon", "Telepon", { tabular: true })}</TableCell>
            <TableCell className="align-top pt-4">{editInput("email", "Email")}</TableCell>
            <TableCell className="align-top pt-4">{editInput("alamat", "Alamat")}</TableCell>
            <TableCell className="align-top pt-4">{editInput("keterangan", "Keterangan")}</TableCell>
            <TableCell className="pr-6 align-top pt-4 text-right">
              <div className="flex justify-end gap-1">
                <Button variant="outline" size="icon" aria-label="Batal Edit" className="h-11 w-11 md:h-8 md:w-8 text-muted-foreground hover:text-foreground" onClick={handleCancelInline} disabled={isPending}>
                  <X className="h-4 w-4" />
                </Button>
                <Button variant="default" size="icon" aria-label="Simpan Edit" className="h-11 w-11 md:h-8 md:w-8" onClick={handleSaveInline} disabled={isPending}>
                  {isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
                </Button>
              </div>
            </TableCell>
          </>
        );
      }}
      actions={[
        { label: "Import CSV", icon: <Upload className="w-4 h-4" />, variant: "outline", onClick: () => setIsImportOpen(true) },
        {
          label: "Export",
          customRender: () => (
            <ExportDropdown
              onExportCSV={handleExportCSV}
              onExportPDF={handleExportPDF}
              className="flex-1 md:flex-none"
            />
          ),
        },
        {
          label: "Tambah Supplier",
          icon: <Plus className="w-4 h-4" />,
          kind: "primary",
          onClick: () => { setEditingId("new"); setEditForm({}); setErrorMsg(""); },
          disabled: editingId !== null,
        },
      ]}
      errorBanner={errorMsg && editingId === 'new' ? errorMsg : null}
      deleteModal={deleteModal}
      emptyState={{
        icon: Truck,
        title: "Tidak ada data supplier ditemukan",
        description: "Coba gunakan kata kunci pencarian atau filter yang lain.",
      }}
    />
    <ImportCSVModal
      open={isImportOpen}
      onOpenChange={setIsImportOpen}
      title="Import Data Supplier"
      description="Unggah file CSV dengan kolom Nama Supplier, Alamat, No. Telepon, Email, dan Keterangan."
      templateFilename="Template_Import_Supplier"
      templateHeaders={["Nama Supplier", "Alamat", "No. Telepon", "Email", "Keterangan"]}
      sampleRows={[
        ["PT Semen Nusantara", "Jl. Industri No. 45, Gresik", "0318901234", "sales@semennusantara.co.id", "Pemasok Semen Utama"],
        ["CV Bina Kayu", "Jl. Raya Kayu No. 8, Jepara", "081987654321", "info@binakayu.com", "Pemasok Kayu & Triplek"],
      ]}
      validateRow={(row) => {
        const name = row["Nama Supplier"] || row["nama_supplier"] || "";
        if (!name.trim()) {
          return "Nama Supplier wajib diisi";
        }
        return null;
      }}
      onImport={importSuppliers}
    />
  </>
  );
}

"use client";

import { useState, useMemo, useDeferredValue } from "react";
import { Search, Receipt, Trash2, AlertTriangle, Loader2, X } from "lucide-react";
import { useTable } from "@/hooks/use-table";
import DataTable, { type Column, type FilterDef } from "@/components/data-table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { useRouter } from "next/navigation";
import { voidTransaction, getTransactionDetails } from "./actions";
import { exportToCSV, exportToPDF } from "@/lib/export-utils";
import { ExportDropdown } from "@/components/export-dropdown";

function formatIDR(n: number) {
  return new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n);
}

function formatDate(dateStr: string) {
  const date = new Date(dateStr);
  return new Intl.DateTimeFormat("id-ID", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

export interface Transaction {
  id: number;
  no_transaksi: string;
  tgl_transaksi: string;
  total: number;
  bayar: number;
  kembali: number;
  pelanggan: { nama_pelanggan: string } | null;
  pengguna: { username: string, nama: string } | null;
  metode_bayar: { id: number, nama: string } | null;
}

interface TransactionDetail {
  id: number;
  qty: number;
  qty_satuan: number | null;
  satuan_jual: string | null;
  harga_jual: number;
  jumlah: number;
  produk: { nama_produk: string } | null;
}

export default function TransactionsClient({
  initialTransactions,
  paymentMethods,
  role
}: {
  initialTransactions: Transaction[];
  paymentMethods: { id: number; nama: string }[];
  role?: string;
}) {
  const router = useRouter();
  const [searchQuery, setSearchQuery] = useState("");
  const deferredSearchQuery = useDeferredValue(searchQuery);
  const [paymentFilter, setPaymentFilter] = useState("all");
  const [dateFilter, setDateFilter] = useState({ start: "", end: "" });

  const [voidModal, setVoidModal] = useState<{ open: boolean; transaction: Transaction | null; items: TransactionDetail[]; loading: boolean }>({
    open: false,
    transaction: null,
    items: [],
    loading: false
  });

  const isOwnerOrAdmin = role === "OWNER" || role === "ADMIN";

  const handleOpenVoid = async (e: React.MouseEvent, t: Transaction) => {
    e.stopPropagation();
    setVoidModal({ open: true, transaction: t, items: [], loading: true });

    const res = await getTransactionDetails(t.id);
    if (res.data) {
      setVoidModal(prev => ({ ...prev, items: res.data as unknown as TransactionDetail[], loading: false }));
    } else {
      setVoidModal(prev => ({ ...prev, loading: false }));
    }
  };

  const handleConfirmVoid = async () => {
    if (!voidModal.transaction) return;
    setVoidModal(prev => ({ ...prev, loading: true }));

    const res = await voidTransaction(voidModal.transaction.id);
    if (res.error) {
      alert("Gagal membatalkan transaksi: " + res.error);
      setVoidModal(prev => ({ ...prev, loading: false }));
    } else {
      setVoidModal({ open: false, transaction: null, items: [], loading: false });
    }
  };

  const filteredData = useMemo(() => {
    let result = [...initialTransactions];

    if (deferredSearchQuery.trim()) {
      const q = deferredSearchQuery.toLowerCase();
      result = result.filter(
        (t) =>
          String(t.no_transaksi).toLowerCase().includes(q) ||
          t.pengguna?.nama?.toLowerCase().includes(q) ||
          t.pengguna?.username?.toLowerCase().includes(q) ||
          t.pelanggan?.nama_pelanggan?.toLowerCase().includes(q)
      );
    }

    if (paymentFilter !== "all") {
      result = result.filter((t) => t.metode_bayar?.id.toString() === paymentFilter);
    }

    if (dateFilter.start) {
      const start = new Date(dateFilter.start);
      start.setHours(0, 0, 0, 0);
      result = result.filter((t) => new Date(t.tgl_transaksi) >= start);
    }
    if (dateFilter.end) {
      const end = new Date(dateFilter.end);
      end.setHours(23, 59, 59, 999);
      result = result.filter((t) => new Date(t.tgl_transaksi) <= end);
    }

    return result;
  }, [initialTransactions, deferredSearchQuery, paymentFilter, dateFilter]);

  const table = useTable({ data: filteredData, defaultItemsPerPage: 25 });

  const totalSales = useMemo(() => {
    return filteredData.reduce((sum, t) => sum + Number(t.total), 0);
  }, [filteredData]);

  const getStatusBadge = (t: Transaction) => {
    if (t.bayar >= t.total) {
      return <Badge variant="secondary" className="bg-success/10 text-success hover:bg-success/20 font-medium border-none rounded-full px-2 py-0.5 text-[10px] uppercase tracking-widest leading-tight">Selesai</Badge>;
    }
    if (t.bayar > 0) {
      return <Badge variant="secondary" className="bg-warning/10 text-warning hover:bg-warning/20 font-medium border-none rounded-full px-2 py-0.5 text-[10px] uppercase tracking-widest leading-tight">Sebagian</Badge>;
    }
    return <Badge variant="secondary" className="bg-destructive/10 text-destructive hover:bg-destructive/20 font-medium border-none rounded-full px-2 py-0.5 text-[10px] uppercase tracking-widest leading-tight">Tertunda</Badge>;
  };

  const handleExportCSV = () => {
    const headers = ["No. Transaksi", "Tanggal", "Kasir", "Pelanggan", "Total", "Pembayaran", "Status"];
    const data = filteredData.map(t => [
      `#${t.no_transaksi}`,
      formatDate(t.tgl_transaksi),
      t.pengguna?.nama || t.pengguna?.username || "-",
      t.pelanggan?.nama_pelanggan || "Umum",
      formatIDR(t.total),
      t.metode_bayar?.nama || "-",
      t.bayar >= t.total ? "Selesai" : (t.bayar > 0 ? "Sebagian" : "Tertunda")
    ]);
    exportToCSV("Data_Transaksi", headers, data);
  };

  const handleExportPDF = () => {
    const headers = ["No. Transaksi", "Tanggal", "Kasir", "Pelanggan", "Total", "Pembayaran", "Status"];
    const data = filteredData.map(t => [
      `#${t.no_transaksi}`,
      formatDate(t.tgl_transaksi),
      t.pengguna?.nama || t.pengguna?.username || "-",
      t.pelanggan?.nama_pelanggan || "Umum",
      formatIDR(t.total),
      t.metode_bayar?.nama || "-",
      t.bayar >= t.total ? "Selesai" : (t.bayar > 0 ? "Sebagian" : "Tertunda")
    ]);
    exportToPDF("Data_Transaksi", "Laporan Data Transaksi", headers, data);
  };

  const filters: FilterDef[] = [
    {
      type: "date-range",
      start: dateFilter.start,
      end: dateFilter.end,
      onStartChange: (v) => setDateFilter(prev => ({ ...prev, start: v })),
      onEndChange: (v) => setDateFilter(prev => ({ ...prev, end: v })),
    },
    {
      type: "select",
      label: "Pembayaran",
      value: paymentFilter,
      onChange: setPaymentFilter,
      options: [
        ...paymentMethods.map((pm) => ({ value: String(pm.id), label: pm.nama })),
      ],
    },
  ];

  const columns: Column<Transaction>[] = [
    { key: "no_transaksi", header: "No. Transaksi", sortable: true, className: "pl-6", headerClassName: "pl-6 w-[180px]", render: (t) => <span>{`#${t.no_transaksi}`}</span> },
    { key: "tgl_transaksi", header: "Tanggal", sortable: true, headerClassName: "w-[180px]", render: (t) => formatDate(t.tgl_transaksi) },
    { key: "kasir", header: "Kasir", sortable: true, sortKey: "pengguna.nama", render: (t) => <p className="text-foreground text-[13px]">{t.pengguna?.nama || t.pengguna?.username || "-"}</p> },
    { key: "pelanggan", header: "Pelanggan", sortable: true, sortKey: "pelanggan.nama_pelanggan", render: (t) => <p className="text-foreground text-[13px]">{t.pelanggan?.nama_pelanggan || "Umum"}</p> },
    { key: "total", header: "Total", sortable: true, headerClassName: "w-[140px] text-right", render: (t) => <span className="tabular-nums">{formatIDR(t.total)}</span> },
    { key: "metode_bayar", header: "Pembayaran", sortable: true, sortKey: "metode_bayar.nama", headerClassName: "w-[140px] text-center", render: (t) => <span className="text-muted-foreground text-[13px]">{t.metode_bayar?.nama || "-"}</span> },
    {
      key: "status", header: "Status", headerClassName: "w-[120px] text-center",
      render: (t) => <div className="flex justify-center">{getStatusBadge(t)}</div>,
    },
    {
      key: "actions", header: "", className: "pr-6", headerClassName: "w-[60px] pr-6",
      render: (t) => (
        <div className="flex justify-end">
          {isOwnerOrAdmin && (
            <Button variant="ghost" size="icon" className="h-11 w-11 md:h-8 md:w-8 text-muted-foreground hover:text-destructive hover:bg-destructive/10" onClick={(e) => handleOpenVoid(e, t)}>
              <Trash2 className="h-4 w-4" />
            </Button>
          )}
        </div>
      ),
    },
  ];

  return (
    <>
      <DataTable
        data={table.paginatedData}
        total={table.total}
        columns={columns}
        rowKey={(t) => t.id}
        search={searchQuery}
        onSearchChange={setSearchQuery}
        searchPlaceholder="Cari No. Transaksi, Kasir, atau Pelanggan..."
        sortConfig={table.sortConfig}
        onSort={table.handleSort}
        currentPage={table.currentPage}
        onPageChange={table.setCurrentPage}
        itemsPerPage={table.itemsPerPage}
        onItemsPerPageChange={table.setItemsPerPage}
        filters={filters}
        onRowClick={(t) => router.push(`/pos/invoice/${t.id}`)}
        actions={[
          { label: "Reset", variant: "outline", onClick: () => { setSearchQuery(""); setPaymentFilter("all"); setDateFilter({ start: "", end: "" }); } },
          {
            label: "Export",
            customRender: () => (
              <ExportDropdown
                onExportCSV={handleExportCSV}
                onExportPDF={handleExportPDF}
                className="flex-1 md:flex-none"
              />
            ),
          },
        ]}
        topContent={
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pb-2">
            <div className="bg-muted/30 rounded-xl p-4 border border-border/50">
              <p className="text-[11px] font-medium text-muted-foreground uppercase tracking-widest mb-1">Total Penjualan</p>
              <p className="text-2xl font-light tracking-tight text-foreground tabular-nums">{formatIDR(totalSales)}</p>
            </div>
            <div className="bg-muted/30 rounded-xl p-4 border border-border/50">
              <p className="text-[11px] font-medium text-muted-foreground uppercase tracking-widest mb-1">Jumlah Transaksi</p>
              <p className="text-2xl font-light tracking-tight text-foreground tabular-nums">{filteredData.length}</p>
            </div>
            <div className="bg-muted/30 rounded-xl p-4 border border-border/50">
              <p className="text-[11px] font-medium text-muted-foreground uppercase tracking-widest mb-1">Rata-rata Transaksi</p>
              <p className="text-2xl font-light tracking-tight text-foreground tabular-nums">
                {filteredData.length > 0 ? formatIDR(totalSales / filteredData.length) : formatIDR(0)}
              </p>
            </div>
          </div>
        }
        emptyState={{
          icon: Receipt,
          title: "Tidak ada transaksi ditemukan",
          description: "Coba gunakan kata kunci pencarian atau filter yang lain.",
        }}
      />

      {/* Void Modal */}
      {voidModal.open && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-overlay/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-background border border-border shadow-[0_8px_24px_rgba(0,55,112,0.08),0_2px_6px_rgba(0,55,112,0.04)] rounded-[12px] w-full max-w-lg flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="shrink-0 flex items-center justify-between px-6 py-5 border-b border-border">
              <h2 className="text-[22px] font-light tracking-tight text-foreground flex items-center gap-2">
                <AlertTriangle className="w-5 h-5 text-destructive" />
                Batalkan Transaksi
              </h2>
              <button
                className="text-muted-foreground hover:text-foreground transition-colors p-1"
                onClick={() => setVoidModal({ open: false, transaction: null, items: [], loading: false })}
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-6 space-y-4">
              <div className="bg-muted/30 rounded-xl p-4 border border-border/50">
                <div className="flex justify-between text-sm mb-1">
                  <span className="text-muted-foreground">No. Transaksi</span>
                  <span className="font-medium">#{voidModal.transaction?.no_transaksi}</span>
                </div>
                <div className="flex justify-between text-sm mb-1">
                  <span className="text-muted-foreground">Tanggal</span>
                  <span>{voidModal.transaction && formatDate(voidModal.transaction.tgl_transaksi)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-muted-foreground">Total</span>
                  <span className="font-semibold text-foreground">{voidModal.transaction && formatIDR(voidModal.transaction.total)}</span>
                </div>
              </div>

              <div>
                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-widest mb-2">Item Transaksi</p>
                <div className="max-h-40 overflow-y-auto space-y-2">
                  {voidModal.loading && voidModal.items.length === 0 ? (
                    <div className="flex items-center justify-center py-4">
                      <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
                    </div>
                  ) : (
                    voidModal.items.map((item, idx) => (
                      <div key={idx} className="flex justify-between text-sm p-2 bg-muted/20 rounded-md">
                        <span className="truncate flex-1 pr-4">{item.produk?.nama_produk}</span>
                        <span className="text-muted-foreground tabular-nums">{item.qty_satuan ?? item.qty} {item.satuan_jual ?? ""} x {formatIDR(item.harga_jual)}</span>
                      </div>
                    ))
                  )}
                </div>
              </div>

              <div className="bg-destructive/10 border border-destructive/20 rounded-lg p-3">
                <p className="text-xs text-destructive leading-relaxed">
                  <strong>Peringatan:</strong> Menghapus transaksi ini bersifat permanen. Stok produk <strong>TIDAK</strong> akan dikembalikan secara otomatis.
                </p>
              </div>
            </div>

            <div className="shrink-0 px-6 py-5 border-t border-border bg-transparent flex flex-col-reverse sm:flex-row justify-end gap-3">
              <Button variant="outline" className="rounded-full px-6 bg-background w-full sm:w-auto" onClick={() => setVoidModal({ open: false, transaction: null, items: [], loading: false })} disabled={voidModal.loading}>
                Batal
              </Button>
              <Button variant="destructive" className="rounded-full px-6 shadow-sm w-full sm:w-auto" onClick={handleConfirmVoid} disabled={voidModal.loading}>
                {voidModal.loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                Konfirmasi Hapus
              </Button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

"use server";

import { createClient } from "@/lib/supabase/server";
import { confirmTutupKasir, getDailyCashSummary, openKasirSession } from "@/lib/laporan-kasir";
import { revalidatePath } from "next/cache";
import { logActivity, buildDeskripsi } from "@/lib/activity-log";

/** Hanya kasir yang boleh membuka/menutup kas kasir. */
async function requireKasir(
  supabase: Awaited<ReturnType<typeof createClient>>
) {
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return { error: "Unauthorized", pengguna: null };

  const { data: pengguna } = await supabase
    .from("pengguna")
    .select("id, level")
    .eq("username", user.email?.split("@")[0])
    .single();

  if (!pengguna) return { error: "User profile not found.", pengguna: null };
  if (pengguna.level !== "KASIR") {
    return {
      error: "Akses ditolak — hanya kasir yang dapat membuka/menutup kas kasir",
      pengguna: null,
    };
  }
  return { error: null, pengguna };
}

/** Hanya owner yang boleh mengoreksi/mengedit saldo kasir (jika salah input). */
async function requireOwner(
  supabase: Awaited<ReturnType<typeof createClient>>
) {
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return { error: "Unauthorized", pengguna: null };

  const { data: pengguna } = await supabase
    .from("pengguna")
    .select("id, level")
    .eq("username", user.email?.split("@")[0])
    .single();

  if (!pengguna) return { error: "User profile not found.", pengguna: null };
  if (pengguna.level !== "OWNER") {
    return {
      error: "Akses ditolak — hanya owner yang dapat mengedit saldo kasir",
      pengguna: null,
    };
  }
  return { error: null, pengguna };
}

export async function fetchCashSummary(date: string) {
  const supabase = await createClient();

  const { error: authErr } = await requireKasir(supabase);
  if (authErr) return { error: authErr };


  try {
    const summary = await getDailyCashSummary(supabase, date);
    return { data: summary };
  } catch {
    return { error: "Gagal mengambil ringkasan kas" };
  }
}

/** Langkah 1 — Buka Sesi Kas Kasir: kasir memasukkan uang awal (float). */
export async function bukaSesiKasir(tanggal: string, uang_awal: number) {
  const supabase = await createClient();

  const { error: authErr, pengguna } = await requireKasir(supabase);
  if (authErr) return { error: authErr };
  if (!pengguna) return { error: authErr || "Unauthorized" };

  if (!tanggal) return { error: "Tanggal wajib diisi" };
  if (!(Number(uang_awal) > 0)) return { error: "Uang awal harus lebih dari 0" };

  try {
    await openKasirSession(supabase, {
      tanggal,
      uang_awal: Number(uang_awal),
      id_pengguna: pengguna.id,
    });

    await logActivity(supabase, {
      aksi: "CREATE",
      entitas: "saldo_kas_harian",
      deskripsi: `Buka sesi kasir ${tanggal}: uang awal ${new Intl.NumberFormat("id-ID").format(Number(uang_awal))}`,
      data_baru: { tanggal, uang_awal: Number(uang_awal) } as unknown as Record<string, unknown>,
    });

    revalidatePath("/dashboard/laporan-kasir");
    revalidatePath("/dashboard/tutup-kasir");
    return { success: true };
  } catch (err: any) {
    console.error("Failed to open kasir session:", err);
    return { error: err?.message || "Gagal membuka sesi kasir" };
  }
}

/** Langkah 2 — Tutup Kasir: hitung ulang di server, simpan uang aktual & selisih. */
export async function submitTutupKasir(params: {
  tanggal: string;
  uang_aktual: number;
}) {
  const supabase = await createClient();

  const { error: authErr, pengguna } = await requireKasir(supabase);
  if (authErr) return { error: authErr };
  if (!pengguna) return { error: authErr || "Unauthorized" };

  if (!params.tanggal) return { error: "Tanggal wajib diisi" };
  const uangAktual = Number(params.uang_aktual);
  if (isNaN(uangAktual) || uangAktual < 0) return { error: "Uang aktual wajib diisi" };

  try {
    // Rekalkulasi server-side (jangan percaya angka dari client)
    const summary = await getDailyCashSummary(supabase, params.tanggal);

    if (!summary.sesi.sudah_dibuka) {
      return { error: "Buka sesi kasir terlebih dahulu sebelum menutup" };
    }
    if (summary.sesi.sudah_ditutup) {
      return { error: "Sesi kasir pada tanggal ini sudah ditutup" };
    }

    await confirmTutupKasir(supabase, {
      tanggal: summary.tanggal,
      uang_awal: summary.uang_awal,
      saldo_awal: summary.saldo_awal,
      total_masuk: summary.total_masuk,
      total_keluar: summary.total_keluar,
      uang_aktual: uangAktual,
      id_pengguna: pengguna.id,
    });

    await logActivity(supabase, {
      aksi: "CREATE",
      entitas: "saldo_kas_harian",
      deskripsi: buildDeskripsi({
        aksi: "CREATE",
        entitas: "saldo_kas_harian",
        data_baru: { tanggal: params.tanggal, uang_awal: summary.uang_awal, uang_aktual: uangAktual, selisih: uangAktual - summary.saldo_akhir_sistem } as unknown as Record<string, unknown>,
      }),
      data_baru: {
        tanggal: params.tanggal,
        uang_awal: summary.uang_awal,
        total_masuk: summary.total_masuk,
        uang_aktual: uangAktual,
        selisih: uangAktual - summary.saldo_akhir_sistem,
      } as unknown as Record<string, unknown>,
    });

    revalidatePath("/dashboard/laporan-kasir");
    revalidatePath("/dashboard/tutup-kasir");
    return { success: true };
  } catch (err: any) {
    console.error("Failed to confirm tutup kasir:", err);
    return { error: "Gagal konfirmasi tutup kasir" };
  }
}

/** Koreksi saldo sesi kasir oleh OWNER (jika kasir/admin salah input).
 *  Uang awal mengubah saldo_awal (saldo_akhir otomatis = saldo_awal + masuk − keluar),
 *  uang aktual mengubah selisih. total_masuk/keluar TIDAK diubah (berasal dari penjualan).
 */
export async function editSesiKasir(params: {
  tanggal: string;
  uang_awal: number;
  uang_aktual: number | null;
}) {
  const supabase = await createClient();

  const { error: authErr, pengguna } = await requireOwner(supabase);
  if (authErr) return { error: authErr };
  if (!pengguna) return { error: authErr || "Unauthorized" };

  if (!params.tanggal) return { error: "Tanggal wajib diisi" };
  const uangAwal = Number(params.uang_awal);
  if (isNaN(uangAwal) || uangAwal < 0) return { error: "Uang awal tidak valid" };
  const uangAktual = params.uang_aktual == null ? null : Number(params.uang_aktual);
  if (uangAktual != null && (isNaN(uangAktual) || uangAktual < 0)) {
    return { error: "Uang aktual tidak valid" };
  }

  try {
    const { data: existing } = await supabase
      .from("saldo_kas_harian")
      .select("tanggal, uang_awal, uang_aktual, total_masuk, dikonfirmasi")
      .eq("tanggal", params.tanggal)
      .maybeSingle();

    if (!existing) {
      return { error: "Sesi kasir pada tanggal ini belum dibuka" };
    }

    const totalMasuk = Number(existing.total_masuk || 0);
    const saldoAkhir = uangAwal + totalMasuk;
    const selisih = uangAktual == null ? null : uangAktual - saldoAkhir;

    const { error } = await supabase
      .from("saldo_kas_harian")
      .update({
        uang_awal: uangAwal,
        saldo_awal: uangAwal,
        uang_aktual: uangAktual,
        selisih,
      })
      .eq("tanggal", params.tanggal);

    if (error) {
      console.error("Failed to edit kasir session:", error);
      return { error: "Gagal mengedit saldo sesi kasir" };
    }

    await logActivity(supabase, {
      aksi: "UPDATE",
      entitas: "saldo_kas_harian",
      deskripsi: `Koreksi saldo sesi kasir ${params.tanggal}: uang awal ${new Intl.NumberFormat("id-ID").format(uangAwal)}${uangAktual != null ? `, uang aktual ${new Intl.NumberFormat("id-ID").format(uangAktual)}` : ""}`,
      data_lama: {
        tanggal: existing.tanggal,
        uang_awal: existing.uang_awal,
        uang_aktual: existing.uang_aktual,
      } as unknown as Record<string, unknown>,
      data_baru: {
        tanggal: params.tanggal,
        uang_awal: uangAwal,
        uang_aktual: uangAktual,
        selisih,
      } as unknown as Record<string, unknown>,
    });

    revalidatePath("/dashboard/laporan-kasir");
    revalidatePath("/dashboard/laporan/kas");
    revalidatePath("/dashboard/tutup-kasir");
    return { success: true };
  } catch (err: any) {
    console.error("Failed to edit kasir session:", err);
    return { error: err?.message || "Gagal mengedit saldo sesi kasir" };
  }
}

